/**
 * PhaseConfigurationStep.tsx — Step 4 of the AzFIT Program Design Wizard
 *
 * Displays configured training phases with auto-suggestions based on the
 * selected method. Users can add, edit, remove, and duplicate phases.
 * Each phase card shows week range, focus, intensity target, and volume target.
 * A dialog editor allows full CRUD on individual phases.
 */

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Plus, Edit3, Trash2, Copy, Layers, Calendar, Target,
  TrendingUp, X, Check, Lightbulb
} from 'lucide-react';
import { Button } from '@/components/ui/button';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from '@/components/ui/dialog';
import { useProgramStore, type WizardPhase } from '@/stores/useProgramStore';

/* ------------------------------------------------------------------ */
/*  HELPERS                                                            */
/* ------------------------------------------------------------------ */

const generateId = () => `phase-${Math.random().toString(36).substring(2, 9)}`;

/* ------------------------------------------------------------------ */
/*  COMPONENT                                                          */
/* ------------------------------------------------------------------ */

export default function PhaseConfigurationStep() {
  const { wizard, addPhase, removePhase, updatePhase } = useProgramStore();
  const { phases, selectedMethod } = wizard;

  // Editor dialog state
  const [editorOpen, setEditorOpen] = useState(false);
  const [editingPhase, setEditingPhase] = useState<WizardPhase | null>(null);
  const [isCreating, setIsCreating] = useState(false);

  // Form state
  const [formName, setFormName] = useState('');
  const [formWeekStart, setFormWeekStart] = useState(1);
  const [formWeekEnd, setFormWeekEnd] = useState(4);
  const [formFocus, setFormFocus] = useState('');
  const [formIntensity, setFormIntensity] = useState('');
  const [formVolume, setFormVolume] = useState('');

  // Auto-suggest message
  const autoSuggest = selectedMethod
    ? `Add phases to structure your program periodization for ${selectedMethod}.`
    : 'Add phases to structure your program periodization.';

  /** Open editor for a new phase */
  const openCreate = () => {
    const nextStart = phases.length > 0
      ? Math.max(...phases.map((p) => p.weekEnd)) + 1
      : 1;
    setIsCreating(true);
    setEditingPhase(null);
    setFormName('');
    setFormWeekStart(nextStart);
    setFormWeekEnd(nextStart + 3);
    setFormFocus('');
    setFormIntensity('RPE 8-9');
    setFormVolume('20 sets/session');
    setEditorOpen(true);
  };

  /** Open editor for existing phase */
  const openEdit = (phase: ProgramPhase) => {
    setIsCreating(false);
    setEditingPhase(phase);
    setFormName(phase.name);
    setFormWeekStart(phase.weekStart);
    setFormWeekEnd(phase.weekEnd);
    setFormFocus(phase.focus);
    setFormIntensity(phase.intensityTarget);
    setFormVolume(phase.volumeTarget);
    setEditorOpen(true);
  };

  /** Save phase (create or update) */
  const handleSave = () => {
    if (!formName.trim()) return;

    const data: Omit<ProgramPhase, 'id' | 'exercises'> = {
      name: formName.trim(),
      weekStart: Math.max(1, formWeekStart),
      weekEnd: Math.max(formWeekStart, formWeekEnd),
      focus: formFocus.trim(),
      intensityTarget: formIntensity.trim(),
      volumeTarget: formVolume.trim(),
    };

    if (isCreating) {
      addPhase({
        ...data,
        exercises: [],
      });
    } else if (editingPhase) {
      updatePhase(editingPhase.id, data);
    }

    setEditorOpen(false);
  };

  /** Duplicate a phase */
  const handleDuplicate = (phase: WizardPhase) => {
    const newPhase: Omit<WizardPhase, 'id'> = {
      name: `${phase.name} (Copy)`,
      description: phase.description,
      order: phase.order,
      weekStart: phase.weekEnd + 1,
      weekEnd: phase.weekEnd + (phase.weekEnd - phase.weekStart) + 1,
      focus: phase.focus,
      intensityTarget: phase.intensityTarget,
      volumeTarget: phase.volumeTarget,
      exercises: phase.exercises,
    };
    addPhase(newPhase);
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Title */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center space-y-2"
      >
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          How many training phases?
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Define the periodization structure for your program
        </p>
      </motion.div>

      {/* Auto-suggest Banner */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="flex items-start gap-3 p-4 rounded-xl bg-gradient-to-r from-[#00AEEF]/5 to-transparent border border-[#00AEEF]/15"
      >
        <Lightbulb className="w-5 h-5 text-[#00AEEF] shrink-0 mt-0.5" />
        <div>
          <p className="text-sm font-medium text-gray-800 dark:text-gray-200">Auto-Suggestion</p>
          <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5">{autoSuggest}</p>
        </div>
      </motion.div>

      {/* Phase Count Quick Select */}
      {phases.length === 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.15 }}
          className="grid grid-cols-2 sm:grid-cols-4 gap-3"
        >
          {[1, 2, 3, 4].map((count) => (
            <button
              key={count}
              onClick={() => {
                // Auto-generate N phases
                for (let i = 0; i < count; i++) {
                  const startWeek = i * 4 + 1;
                  addPhase({
                    name: `Phase ${i + 1}`,
                    weekStart: startWeek,
                    weekEnd: startWeek + 3,
                    focus: i === 0 ? 'Work capacity & technique' : i === count - 1 ? 'Peak & intensification' : 'Strength accumulation',
                    intensityTarget: `RPE ${7 + i}-${8 + i}`,
                    volumeTarget: `${16 + i * 4} sets/session`,
                    exercises: [],
                  });
                }
              }}
              className="flex flex-col items-center gap-2 p-4 border border-gray-200 dark:border-white/10 rounded-xl hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10 transition-all"
            >
              <span className="text-2xl font-bold text-[#00AEEF]">{count}</span>
              <span className="text-xs text-gray-500 dark:text-gray-400">
                {count * 4} weeks est.
              </span>
            </button>
          ))}
        </motion.div>
      )}

      {/* Phase Cards */}
      <div className="space-y-3">
        <AnimatePresence mode="popLayout">
          {phases.map((phase, index) => (
            <motion.div
              key={phase.id}
              layout
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              exit={{ opacity: 0, x: 20, transition: { duration: 0.2 } }}
              transition={{ delay: index * 0.08, duration: 0.3 }}
              className="flex items-center gap-4 p-4 rounded-2xl bg-white dark:bg-[#141414] border border-gray-100 dark:border-white/5 hover:border-gray-200 dark:hover:border-white/10 transition-all group"
            >
              {/* Phase Number */}
              <div className="w-10 h-10 rounded-xl bg-[#00AEEF]/10 flex items-center justify-center shrink-0">
                <span className="text-sm font-bold text-[#00AEEF]">{index + 1}</span>
              </div>

              {/* Phase Info */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="font-semibold text-sm text-gray-900 dark:text-white">
                    {phase.name}
                  </h3>
                  <Badge variant="outline" className="text-[9px] px-1.5">
                    <Calendar className="w-2.5 h-2.5 mr-1" />
                    Wk {phase.weekStart}–{phase.weekEnd}
                  </Badge>
                </div>
                <p className="text-xs text-gray-500 dark:text-gray-400 mt-1 truncate">
                  {phase.focus}
                </p>
                <div className="flex items-center gap-3 mt-2">
                  <span className="flex items-center gap-1 text-[10px] text-gray-400">
                    <Target className="w-3 h-3" />
                    {phase.intensityTarget}
                  </span>
                  <span className="flex items-center gap-1 text-[10px] text-gray-400">
                    <TrendingUp className="w-3 h-3" />
                    {phase.volumeTarget}
                  </span>
                  <span className="flex items-center gap-1 text-[10px] text-gray-400">
                    <Layers className="w-3 h-3" />
                    {phase.exercises.length} exercises
                  </span>
                </div>
              </div>

              {/* Actions */}
              <div className="flex items-center gap-1 shrink-0 opacity-0 group-hover:opacity-100 transition-opacity sm:opacity-100">
                <Button
                  variant="ghost"
                  size="icon"
                  className="w-8 h-8 text-gray-400 hover:text-[#00AEEF] hover:bg-[#00AEEF]/5"
                  onClick={() => openEdit(phase)}
                >
                  <Edit3 className="w-3.5 h-3.5" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="w-8 h-8 text-gray-400 hover:text-[#22C55E] hover:bg-[#22C55E]/5"
                  onClick={() => handleDuplicate(phase)}
                >
                  <Copy className="w-3.5 h-3.5" />
                </Button>
                <Button
                  variant="ghost"
                  size="icon"
                  className="w-8 h-8 text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20"
                  onClick={() => removePhase(phase.id)}
                >
                  <Trash2 className="w-3.5 h-3.5" />
                </Button>
              </div>
            </motion.div>
          ))}
        </AnimatePresence>

        {/* Empty state */}
        {phases.length === 0 && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center py-12 rounded-2xl border-2 border-dashed border-gray-100 dark:border-white/5"
          >
            <Layers className="w-10 h-10 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <p className="text-sm text-gray-500 dark:text-gray-400 mb-1">No phases configured yet.</p>
            <p className="text-xs text-gray-400 dark:text-gray-500 mb-4">
              Select a count above or add phases manually.
            </p>
          </motion.div>
        )}

        {/* Add Phase Button */}
        {phases.length > 0 && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            transition={{ delay: 0.3 }}
          >
            <Button
              variant="outline"
              className="w-full h-12 border-dashed border-2 border-gray-200 dark:border-white/10 text-gray-500 dark:text-gray-400 hover:border-[#00AEEF] hover:text-[#00AEEF] hover:bg-[#00AEEF]/5 gap-2"
              onClick={openCreate}
            >
              <Plus className="w-4 h-4" />
              Add Phase
            </Button>
          </motion.div>
        )}
      </div>

      {/* Phase Editor Dialog */}
      <Dialog open={editorOpen} onOpenChange={setEditorOpen}>
        <DialogContent className="max-w-md">
          <DialogHeader>
            <DialogTitle className="text-lg font-bold text-gray-900 dark:text-white">
              {isCreating ? 'Add Training Phase' : 'Edit Training Phase'}
            </DialogTitle>
            <DialogDescription className="text-sm text-gray-500 dark:text-gray-400">
              Define the phase name, week range, training focus, and load targets.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-4 mt-2">
            {/* Phase Name */}
            <div className="space-y-1.5">
              <Label htmlFor="phase-name" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                Phase Name
              </Label>
              <Input
                id="phase-name"
                value={formName}
                onChange={(e) => setFormName(e.target.value)}
                placeholder="e.g. Foundation, Strength, Peak..."
                className="text-sm"
              />
            </div>

            {/* Week Range */}
            <div className="grid grid-cols-2 gap-3">
              <div className="space-y-1.5">
                <Label htmlFor="week-start" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                  Week Start
                </Label>
                <Input
                  id="week-start"
                  type="number"
                  min={1}
                  value={formWeekStart}
                  onChange={(e) => setFormWeekStart(parseInt(e.target.value) || 1)}
                  className="text-sm"
                />
              </div>
              <div className="space-y-1.5">
                <Label htmlFor="week-end" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                  Week End
                </Label>
                <Input
                  id="week-end"
                  type="number"
                  min={formWeekStart}
                  value={formWeekEnd}
                  onChange={(e) => setFormWeekEnd(parseInt(e.target.value) || formWeekStart)}
                  className="text-sm"
                />
              </div>
            </div>

            {/* Focus */}
            <div className="space-y-1.5">
              <Label htmlFor="phase-focus" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                Training Focus
              </Label>
              <Input
                id="phase-focus"
                value={formFocus}
                onChange={(e) => setFormFocus(e.target.value)}
                placeholder="e.g. Work capacity & metabolic stress"
                className="text-sm"
              />
            </div>

            {/* Intensity Target */}
            <div className="space-y-1.5">
              <Label htmlFor="intensity" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                Intensity Target
              </Label>
              <Input
                id="intensity"
                value={formIntensity}
                onChange={(e) => setFormIntensity(e.target.value)}
                placeholder="e.g. RPE 8-9, 80-85% 1RM"
                className="text-sm"
              />
            </div>

            {/* Volume Target */}
            <div className="space-y-1.5">
              <Label htmlFor="volume" className="text-xs font-medium text-gray-700 dark:text-gray-300">
                Volume Target
              </Label>
              <Input
                id="volume"
                value={formVolume}
                onChange={(e) => setFormVolume(e.target.value)}
                placeholder="e.g. 24 sets/session"
                className="text-sm"
              />
            </div>
          </div>

          <DialogFooter className="mt-4">
            <Button variant="outline" size="sm" onClick={() => setEditorOpen(false)} className="gap-1">
              <X className="w-3.5 h-3.5" />
              Cancel
            </Button>
            <Button
              size="sm"
              onClick={handleSave}
              disabled={!formName.trim()}
              className="gap-1 bg-gradient-to-r from-[#00AEEF] to-[#33BFF2] text-white hover:opacity-90"
            >
              <Check className="w-3.5 h-3.5" />
              {isCreating ? 'Add Phase' : 'Save Changes'}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}
