/**
 * MethodSelectionStep.tsx — Step 2 of the AzFIT Program Design Wizard
 *
 * Displays training method options as horizontal cards. Users select
 * their exercise organization method (Straight Sets, Supersets, Trisets).
 * Also includes difficulty and equipment filters.
 */

import { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import {
  Layers, GitMerge, Triangle, ChevronRight, Check,
  Filter, X, Star,
} from 'lucide-react';
import { useProgramStore, type GoalType, type DifficultyLevel } from '@/stores/useProgramStore';
import { cn } from '@/lib/utils';

/* ------------------------------------------------------------------ */
/*  POLIQUIN METHOD CONFIG                                             */
/* ------------------------------------------------------------------ */

interface PoliquinMethodOption {
  value: string;
  label: string;
  notation: string;
  description: string;
  icon: React.ElementType;
}

const POLIQUIN_METHODS: PoliquinMethodOption[] = [
  {
    value: 'straight',
    label: 'Straight Sets',
    notation: 'A, B, C',
    description: 'Complete all sets of A, then move to B — classic approach',
    icon: Layers,
  },
  {
    value: 'superset',
    label: 'Supersets',
    notation: 'A1, A2',
    description: 'Alternate A1 and A2 exercises — time efficient',
    icon: GitMerge,
  },
  {
    value: 'triset',
    label: 'Trisets',
    notation: 'A1, A2, A3',
    description: 'A1→A2→A3 in sequence — advanced density',
    icon: Triangle,
  },
];

/* ------------------------------------------------------------------ */
/*  FILTER CONFIG                                                      */
/* ------------------------------------------------------------------ */

const LEVELS: ('all' | DifficultyLevel)[] = ['all', 'beginner', 'intermediate', 'advanced'];

const EQUIPMENT_FILTERS = ['Barbell', 'Dumbbells', 'Cable', 'Machine', 'Bodyweight', 'Kettlebell'];

/** Score each method for "best match" ranking against the selected goal */
function scoreMethodForGoal(methodId: string, goal: GoalType): number {
  const scores: Record<string, Record<string, number>> = {
    'method-gbc': { 'lose-fat': 10, 'build-muscle': 7, strength: 3, endurance: 5, maintenance: 4 },
    'method-5x5': { 'lose-fat': 3, 'build-muscle': 8, strength: 10, endurance: 2, maintenance: 6 },
    'method-ppl': { 'lose-fat': 5, 'build-muscle': 10, strength: 7, endurance: 4, maintenance: 5 },
    'method-dup': { 'lose-fat': 4, 'build-muscle': 8, strength: 9, endurance: 6, maintenance: 7 },
    'method-hiit': { 'lose-fat': 9, 'build-muscle': 4, strength: 2, endurance: 8, maintenance: 6 },
    'method-ul':  { 'lose-fat': 5, 'build-muscle': 7, strength: 7, endurance: 5, maintenance: 8 },
  };
  return scores[methodId]?.[goal] ?? 5;
}

/* ------------------------------------------------------------------ */
/*  COMPONENT                                                          */
/* ------------------------------------------------------------------ */

export default function MethodSelectionStep() {
  const { wizard, setWizardMethod, setWizardMethodType, getMethodsForGoal } = useProgramStore();
  const { selectedGoal, selectedMethod, selectedMethodType: methodType } = wizard;

  // Local filter state
  const [levelFilter, setLevelFilter] = useState<'all' | DifficultyLevel>('all');
  const [equipFilter, setEquipFilter] = useState<string[]>([]);

  // Get methods filtered by goal
  const goalMethods = useMemo(
    () => (selectedGoal ? getMethodsForGoal(selectedGoal) : []),
    [selectedGoal, getMethodsForGoal]
  );

  // Apply additional filters
  const filteredMethods = useMemo(() => {
    let list = goalMethods;

    if (levelFilter !== 'all') {
      list = list.filter((m) => m.difficulty === levelFilter);
    }

    if (equipFilter.length > 0) {
      list = list.filter((m) =>
        equipFilter.every((eq) => m.equipment.includes(eq))
      );
    }

    return list;
  }, [goalMethods, levelFilter, equipFilter]);

  // Determine best match (highest score for selected goal)
  const bestMatchId = useMemo(() => {
    if (!selectedGoal || filteredMethods.length === 0) return null;
    const scored = filteredMethods.map((m) => ({
      id: m.id,
      score: scoreMethodForGoal(m.id, selectedGoal),
    }));
    scored.sort((a, b) => b.score - a.score);
    return scored[0]?.id ?? null;
  }, [filteredMethods, selectedGoal]);

  // Toggle equipment filter
  const toggleEquip = (eq: string) => {
    setEquipFilter((prev) =>
      prev.includes(eq) ? prev.filter((e) => e !== eq) : [...prev, eq]
    );
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Title */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center space-y-2"
      >
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          Choose your training method
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          How do you want to organize exercises within each session?
        </p>
      </motion.div>

      {/* Method Type Cards */}
      <div className="space-y-3">
        {POLIQUIN_METHODS.map((method, index) => {
          const isActive = methodType === method.value;
          const Icon = method.icon;

          return (
            <motion.button
              key={method.value}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.08, duration: 0.35 }}
              whileHover={{ x: 4 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => setWizardMethodType(method.value as 'straight' | 'superset' | 'triset')}
              className={cn(
                'w-full flex items-center gap-4 p-5 border rounded-xl cursor-pointer transition-all group text-left',
                isActive
                  ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                  : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10'
              )}
            >
              {/* Left: Icon in circle */}
              <div
                className={cn(
                  'flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-colors',
                  isActive
                    ? 'bg-[#00AEEF]'
                    : 'bg-cyan-50 dark:bg-cyan-950/20 group-hover:bg-[#00AEEF]'
                )}
              >
                {isActive ? (
                  <Check className="w-5 h-5 text-white" />
                ) : (
                  <Icon
                    className={cn(
                      'w-5 h-5 text-[#00AEEF] transition-colors',
                      'group-hover:text-white'
                    )}
                  />
                )}
              </div>

              {/* Center: Title + Description */}
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2">
                  <h3 className="font-semibold text-gray-900 dark:text-white">
                    {method.label}
                  </h3>
                  <span className="text-[10px] px-2 py-0.5 rounded-full bg-gray-100 dark:bg-[#1a1a1a] text-gray-500 dark:text-gray-400 font-mono">
                    {method.notation}
                  </span>
                </div>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
                  {method.description}
                </p>
              </div>

              {/* Right: Chevron */}
              <ChevronRight
                className={cn(
                  'w-5 h-5 flex-shrink-0 transition-colors',
                  isActive
                    ? 'text-[#00AEEF]'
                    : 'text-gray-300 dark:text-gray-600 group-hover:text-[#00AEEF]'
                )}
              />
            </motion.button>
          );
        })}
      </div>

      {/* Filters */}
      <motion.div
        initial={{ opacity: 0 }}
        animate={{ opacity: 1 }}
        transition={{ delay: 0.2 }}
        className="rounded-xl border border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] p-4 space-y-3"
      >
        <div className="flex items-center gap-2 text-gray-500 dark:text-gray-400 mb-2">
          <Filter className="w-4 h-4" />
          <span className="text-xs font-medium uppercase tracking-wider">Filters</span>
        </div>

        {/* Level filter */}
        <div className="flex items-center gap-1.5 flex-wrap">
          {LEVELS.map((lvl) => (
            <button
              key={lvl}
              onClick={() => setLevelFilter(lvl)}
              className={cn(
                'px-3 py-1.5 rounded-full text-xs font-medium transition-all capitalize',
                levelFilter === lvl
                  ? 'bg-[#00AEEF] text-white shadow-sm'
                  : 'bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-400 border border-gray-200 dark:border-white/10 hover:border-gray-300 dark:hover:border-white/20'
              )}
            >
              {lvl}
            </button>
          ))}
        </div>

        {/* Equipment filter */}
        <div className="flex items-center gap-1.5 flex-wrap">
          {EQUIPMENT_FILTERS.map((eq) => (
            <button
              key={eq}
              onClick={() => toggleEquip(eq)}
              className={cn(
                'px-3 py-1.5 rounded-full text-xs font-medium transition-all',
                equipFilter.includes(eq)
                  ? 'bg-[#EC4899] text-white shadow-sm'
                  : 'bg-gray-50 dark:bg-white/5 text-gray-600 dark:text-gray-400 border border-gray-200 dark:border-white/10 hover:border-gray-300 dark:hover:border-white/20'
              )}
            >
              {eq}
            </button>
          ))}
          {equipFilter.length > 0 && (
            <button
              onClick={() => setEquipFilter([])}
              className="p-1.5 rounded-full text-gray-400 hover:text-gray-600 dark:hover:text-gray-200 transition-colors"
            >
              <X className="w-3.5 h-3.5" />
            </button>
          )}
        </div>
      </motion.div>

      {/* Filtered Method List (if user wants to select a specific method) */}
      {filteredMethods.length > 0 && (
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="space-y-3"
        >
          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
            Matching Programs
          </p>
          {filteredMethods.map((method, index) => {
            const isSelected = selectedMethod === method.id;
            const isBestMatch = method.id === bestMatchId;

            return (
              <motion.button
                key={method.id}
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                transition={{ delay: 0.3 + index * 0.08, duration: 0.35 }}
                whileHover={{ x: 4 }}
                whileTap={{ scale: 0.98 }}
                onClick={() => setWizardMethod(method.id)}
                className={cn(
                  'w-full flex items-center gap-4 p-4 border rounded-xl cursor-pointer transition-all group text-left',
                  isSelected
                    ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                    : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10'
                )}
              >
                {/* Best match badge */}
                {isBestMatch && (
                  <div className="absolute -top-2 -right-2 px-2 py-0.5 rounded-full bg-[#00AEEF] text-white text-[10px] font-medium flex items-center gap-1">
                    <Star className="w-3 h-3" />
                    Best Match
                  </div>
                )}

                {/* Center: Title + Description */}
                <div className="flex-1 min-w-0">
                  <div className="flex items-center gap-2">
                    <h3 className="font-semibold text-gray-900 dark:text-white text-sm">
                      {method.shortName}
                    </h3>
                    <span className={cn(
                      'text-[10px] px-1.5 py-0.5 rounded-full',
                      method.difficulty === 'beginner' && 'bg-green-50 text-green-600 dark:bg-green-900/20',
                      method.difficulty === 'intermediate' && 'bg-amber-50 text-amber-600 dark:bg-amber-900/20',
                      method.difficulty === 'advanced' && 'bg-red-50 text-red-600 dark:bg-red-900/20'
                    )}>
                      {method.difficulty}
                    </span>
                  </div>
                  <p className="text-xs text-gray-500 dark:text-gray-400 mt-0.5 line-clamp-2">
                    {method.description}
                  </p>
                  <div className="flex items-center gap-2 mt-1.5 text-[10px] text-gray-400">
                    <span>{method.frequency}x/week</span>
                    <span>•</span>
                    <span>{method.duration} weeks</span>
                  </div>
                </div>

                {/* Right: Chevron */}
                <ChevronRight
                  className={cn(
                    'w-5 h-5 flex-shrink-0 transition-colors',
                    isSelected
                      ? 'text-[#00AEEF]'
                      : 'text-gray-300 dark:text-gray-600 group-hover:text-[#00AEEF]'
                  )}
                />
              </motion.button>
            );
          })}
        </motion.div>
      )}
    </div>
  );
}
