/**
 * ExercisePicker.tsx — Searchable exercise selection dropdown
 *
 * Provides a popover with search input, filter tabs (All / By Muscle / By Equipment),
 * scrollable results showing exercise name + muscle group + equipment tags,
 * and a "Custom Exercise" option at the bottom.
 */

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search,
  X,
  Dumbbell,
  Target,
  Layers,
  Plus,
  ChevronRight,
} from 'lucide-react';
import type { ExerciseDefinition as StoreExerciseDefinition } from '@/stores/useProgramStore';
import { useProgramStore } from '@/stores/useProgramStore';

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface ExercisePickerProps {
  open: boolean;
  onClose: () => void;
  onSelectExercise: (exercise: StoreExerciseDefinition) => void;
}

type FilterTab = 'all' | 'muscle' | 'equipment';

const EASING = [0.16, 1, 0.3, 1] as [number, number, number, number];

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function ExercisePicker({ open, onClose, onSelectExercise }: ExercisePickerProps) {
  const exercises = useProgramStore((s) => s.exercises);

  const [searchQuery, setSearchQuery] = useState('');
  const [activeTab, setActiveTab] = useState<FilterTab>('all');
  const [selectedFilter, setSelectedFilter] = useState('All');
  const [showCustomForm, setShowCustomForm] = useState(false);
  const [customName, setCustomName] = useState('');

  /** Unique muscle groups from exercise library */
  const muscleGroups = useMemo(() => {
    const groups = new Set(exercises.map((e) => e.muscleGroup).filter(Boolean));
    return ['All', ...Array.from(groups).sort()];
  }, [exercises]);

  /** Unique equipment types from exercise library */
  const equipmentTypes = useMemo(() => {
    const types = new Set(exercises.map((e) => e.equipment).filter(Boolean));
    return ['All', ...Array.from(types).sort()];
  }, [exercises]);

  /** Filtered exercises based on search + active tab filter */
  const filtered = useMemo(() => {
    return exercises.filter((ex) => {
      // Search query
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const searchable = `${ex.name} ${ex.muscleGroup} ${ex.equipment}`.toLowerCase();
        if (!searchable.includes(q)) return false;
      }

      // Tab filter
      if (activeTab === 'muscle' && selectedFilter !== 'All' && ex.muscleGroup !== selectedFilter)
        return false;
      if (activeTab === 'equipment' && selectedFilter !== 'All' && ex.equipment !== selectedFilter)
        return false;

      return true;
    });
  }, [exercises, searchQuery, activeTab, selectedFilter]);

  /** Handle custom exercise submission */
  const handleCustomSubmit = () => {
    if (!customName.trim()) return;
    const custom: StoreExerciseDefinition = {
      id: `custom-${Date.now()}`,
      name: customName.trim(),
      muscleGroup: 'Custom',
      equipment: 'Custom',
      difficulty: 'intermediate',
      description: '',
      category: 'full-body',
      primaryMuscles: ['Custom'],
    };
    onSelectExercise(custom);
    setCustomName('');
    setShowCustomForm(false);
    setSearchQuery('');
    setSelectedFilter('All');
  };

  if (!open) return null;

  return (
    <>
      {/* Backdrop */}
      <div className="fixed inset-0 z-40" onClick={onClose} />

      {/* Popover */}
      <motion.div
        initial={{ opacity: 0, y: -8, scale: 0.96 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        exit={{ opacity: 0, y: -8, scale: 0.96 }}
        transition={{ duration: 0.18, ease: EASING }}
        className="absolute left-4 right-4 z-50 mt-2 rounded-xl bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 shadow-xl overflow-hidden"
      >
        {/* Search input */}
        <div className="p-3 border-b border-gray-100 dark:border-white/5">
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-3.5 h-3.5 text-gray-400" />
            <input
              autoFocus
              type="text"
              placeholder="Search exercises..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-9 pr-8 py-2 rounded-lg text-xs bg-gray-50 dark:bg-[#141414] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30 focus:border-[#00AEEF] transition-all"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-2 top-1/2 -translate-y-1/2 p-0.5 rounded text-gray-400 hover:text-gray-600 transition-colors"
              >
                <X className="w-3 h-3" />
              </button>
            )}
          </div>
        </div>

        {/* Filter tabs */}
        <div className="flex items-center gap-1 px-3 py-2 border-b border-gray-100 dark:border-white/5">
          {[
            { key: 'all' as FilterTab, label: 'All', icon: Dumbbell },
            { key: 'muscle' as FilterTab, label: 'By Muscle', icon: Target },
            { key: 'equipment' as FilterTab, label: 'By Equipment', icon: Layers },
          ].map((tab) => (
            <button
              key={tab.key}
              onClick={() => {
                setActiveTab(tab.key);
                setSelectedFilter('All');
              }}
              className={`flex items-center gap-1 px-2.5 py-1 rounded-md text-[11px] font-medium transition-colors ${
                activeTab === tab.key
                  ? 'bg-[#00AEEF]/10 text-[#00AEEF]'
                  : 'text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300'
              }`}
            >
              <tab.icon className="w-3 h-3" />
              {tab.label}
            </button>
          ))}
        </div>

        {/* Sub-filter chips (muscle or equipment) */}
        <AnimatePresence mode="wait">
          {activeTab !== 'all' && (
            <motion.div
              key={activeTab}
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              exit={{ height: 0, opacity: 0 }}
              transition={{ duration: 0.15 }}
              className="overflow-hidden"
            >
              <div className="flex flex-wrap gap-1 px-3 py-2 border-b border-gray-100 dark:border-white/5">
                {(activeTab === 'muscle' ? muscleGroups : equipmentTypes).map((item) => (
                  <button
                    key={item}
                    onClick={() => setSelectedFilter(item)}
                    className={`px-2 py-0.5 rounded-md text-[10px] font-medium transition-colors ${
                      selectedFilter === item
                        ? 'bg-[#00AEEF] text-white'
                        : 'bg-gray-100 text-gray-600 dark:bg-[#222] dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-[#333]'
                    }`}
                  >
                    {item}
                  </button>
                ))}
              </div>
            </motion.div>
          )}
        </AnimatePresence>

        {/* Results list */}
        <div className="max-h-60 overflow-y-auto">
          {filtered.length === 0 ? (
            <div className="px-4 py-6 text-center">
              <p className="text-xs text-gray-400 dark:text-gray-500">No exercises found.</p>
            </div>
          ) : (
            <div className="divide-y divide-gray-50 dark:divide-white/[0.02]">
              {filtered.map((exercise) => (
                <button
                  key={exercise.id}
                  onClick={() => {
                    onSelectExercise(exercise);
                    setSearchQuery('');
                    setSelectedFilter('All');
                  }}
                  className="w-full flex items-center gap-3 px-4 py-2.5 text-left hover:bg-gray-50 dark:hover:bg-white/[0.03] transition-colors group"
                >
                  <div className="flex-1 min-w-0">
                    <p className="text-xs font-medium text-gray-900 dark:text-white truncate group-hover:text-[#00AEEF] transition-colors">
                      {exercise.name}
                    </p>
                    <div className="flex items-center gap-1.5 mt-0.5">
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 dark:bg-[#222] text-gray-500 dark:text-gray-400">
                        {exercise.muscleGroup}
                      </span>
                      <span className="text-[10px] px-1.5 py-0.5 rounded bg-gray-100 dark:bg-[#222] text-gray-500 dark:text-gray-400">
                        {exercise.equipment}
                      </span>
                    </div>
                  </div>
                  <ChevronRight className="w-3 h-3 text-gray-300 group-hover:text-[#00AEEF] transition-colors" />
                </button>
              ))}
            </div>
          )}
        </div>

        {/* Custom exercise section */}
        <div className="border-t border-gray-100 dark:border-white/5 p-3">
          {showCustomForm ? (
            <motion.div
              initial={{ height: 0, opacity: 0 }}
              animate={{ height: 'auto', opacity: 1 }}
              className="flex items-center gap-2"
            >
              <input
                autoFocus
                type="text"
                placeholder="Enter custom exercise name..."
                value={customName}
                onChange={(e) => setCustomName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === 'Enter') handleCustomSubmit();
                  if (e.key === 'Escape') {
                    setShowCustomForm(false);
                    setCustomName('');
                  }
                }}
                className="flex-1 px-3 py-1.5 rounded-lg text-xs bg-gray-50 dark:bg-[#141414] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
              />
              <button
                onClick={handleCustomSubmit}
                disabled={!customName.trim()}
                className="px-3 py-1.5 rounded-lg text-xs font-medium bg-[#00AEEF] text-white hover:bg-[#0095CC] disabled:opacity-40 transition-colors"
              >
                Add
              </button>
              <button
                onClick={() => {
                  setShowCustomForm(false);
                  setCustomName('');
                }}
                className="p-1.5 rounded-lg text-gray-400 hover:text-gray-600 transition-colors"
              >
                <X className="w-3 h-3" />
              </button>
            </motion.div>
          ) : (
            <button
              onClick={() => setShowCustomForm(true)}
              className="flex items-center gap-1.5 text-xs font-medium text-gray-500 dark:text-gray-400 hover:text-[#00AEEF] transition-colors"
            >
              <Plus className="w-3.5 h-3.5" />
              Custom Exercise
            </button>
          )}
        </div>
      </motion.div>
    </>
  );
}
