/**
 * ExerciseBlock.tsx — Displays and edits a single exercise block
 *
 * Shows a block header (name, format selector, delete), a list of exercises
 * with Poliquin group badges (A1, A2, B…), inline-editable fields, drag-to-
 * reorder handles, and a footer to add more exercises. Uses Framer Motion
 * for layout and entry/exit animations.
 */

import { useState, useCallback } from 'react';
import { motion, Reorder, AnimatePresence } from 'framer-motion';
import {
  GripVertical,
  X,
  Plus,
  ChevronDown,
  Layers,
  Repeat,
  CircuitBoard,
  Dumbbell,
  Zap,
  Trash2,
  Info,
} from 'lucide-react';
import type { ProgramExerciseBlock, BlockExercise, BlockFormat } from '@/types/program';
import { cn } from '@/lib/utils';
import ExercisePicker from './ExercisePicker';

// ─────────────────────────────────────────────────────────────────────────────
// Constants
// ─────────────────────────────────────────────────────────────────────────────

const FORMAT_OPTIONS: Array<{
  value: BlockFormat;
  label: string;
  description: string;
  icon: typeof Dumbbell;
}> = [
  {
    value: 'straight',
    label: 'Straight Sets',
    description: 'All sets of one exercise, then next',
    icon: Dumbbell,
  },
  {
    value: 'superset',
    label: 'Supersets',
    description: 'Alternate between 2 exercises',
    icon: Repeat,
  },
  {
    value: 'triset',
    label: 'Trisets',
    description: '3 exercises back-to-back',
    icon: Layers,
  },
  {
    value: 'circuit',
    label: 'Circuit',
    description: 'Complete all exercises, rest, repeat',
    icon: CircuitBoard,
  },
  {
    value: 'giant',
    label: 'Giant Set',
    description: '4+ exercises, minimal rest between',
    icon: Zap,
  },
];

const GROUP_COLORS: Record<string, string> = {
  A: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A1: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A2: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A3: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A4: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A5: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  A6: 'bg-cyan-100 text-cyan-700 dark:bg-cyan-900/40 dark:text-cyan-300',
  B: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B1: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B2: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B3: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B4: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B5: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  B6: 'bg-emerald-100 text-emerald-700 dark:bg-emerald-900/40 dark:text-emerald-300',
  C: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  C1: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  C2: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  C3: 'bg-amber-100 text-amber-700 dark:bg-amber-900/40 dark:text-amber-300',
  D: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  D1: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  D2: 'bg-purple-100 text-purple-700 dark:bg-purple-900/40 dark:text-purple-300',
  E: 'bg-pink-100 text-pink-700 dark:bg-pink-900/40 dark:text-pink-300',
  E1: 'bg-pink-100 text-pink-700 dark:bg-pink-900/40 dark:text-pink-300',
  F: 'bg-rose-100 text-rose-700 dark:bg-rose-900/40 dark:text-rose-300',
};

const EASING = [0.16, 1, 0.3, 1] as [number, number, number, number];

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface ExerciseBlockProps {
  block: ProgramExerciseBlock;
  onUpdateName: (name: string) => void;
  onUpdateFormat: (format: BlockFormat) => void;
  onDeleteBlock: () => void;
  onUpdateExercise: (exerciseId: string, data: Partial<BlockExercise>) => void;
  onRemoveExercise: (exerciseId: string) => void;
  onReorderExercises: (exerciseIds: string[]) => void;
  onAddExercise: (exercise: Omit<BlockExercise, 'id' | 'exerciseGroup'>) => void;
}

// ─────────────────────────────────────────────────────────────────────────────
// Inline edit cell — reusable
// ─────────────────────────────────────────────────────────────────────────────

interface EditCellProps {
  value: string | number;
  onSave: (val: string) => void;
  type?: 'text' | 'number';
  className?: string;
  min?: number;
  max?: number;
  title?: string;
}

function EditCell({ value, onSave, type = 'text', className, min, max, title }: EditCellProps) {
  const [editing, setEditing] = useState(false);

  const handleBlur = (e: React.FocusEvent<HTMLInputElement>) => {
    onSave(e.target.value);
    setEditing(false);
  };

  const handleKeyDown = (e: React.KeyboardEvent<HTMLInputElement>) => {
    if (e.key === 'Enter') {
      onSave(e.currentTarget.value);
      setEditing(false);
    }
    if (e.key === 'Escape') {
      setEditing(false);
    }
  };

  if (editing) {
    return (
      <input
        autoFocus
        type={type}
        defaultValue={value}
        onBlur={handleBlur}
        onKeyDown={handleKeyDown}
        min={min}
        max={max}
        title={title}
        className={cn(
          'px-1 py-0.5 text-xs rounded border border-[#00AEEF] bg-white dark:bg-[#1a1a1a] text-gray-900 dark:text-white text-center focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30',
          className
        )}
      />
    );
  }

  return (
    <button
      onClick={() => setEditing(true)}
      className={cn(
        'px-1 py-0.5 text-xs rounded border border-transparent hover:border-gray-300 dark:hover:border-gray-600 text-gray-700 dark:text-gray-300 transition-colors',
        className
      )}
      title={title}
    >
      {value}
    </button>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function ExerciseBlock({
  block,
  onUpdateName,
  onUpdateFormat,
  onDeleteBlock,
  onUpdateExercise,
  onRemoveExercise,
  onReorderExercises,
  onAddExercise,
}: ExerciseBlockProps) {
  const [editingName, setEditingName] = useState(false);
  const [showFormatMenu, setShowFormatMenu] = useState(false);
  const [showExercisePicker, setShowExercisePicker] = useState(false);

  const currentFormat = FORMAT_OPTIONS.find((f) => f.value === block.format);

  const handleNameSave = useCallback(
    (val: string) => {
      if (val.trim()) onUpdateName(val.trim());
      setEditingName(false);
    },
    [onUpdateName]
  );

  const handleFormatChange = useCallback(
    (format: BlockFormat) => {
      onUpdateFormat(format);
      setShowFormatMenu(false);
    },
    [onUpdateFormat]
  );

  const handleReorder = useCallback(
    (reordered: BlockExercise[]) => {
      onReorderExercises(reordered.map((e) => e.id));
    },
    [onReorderExercises]
  );

  return (
    <motion.div
      layout
      initial={{ opacity: 0, y: -20 }}
      animate={{ opacity: 1, y: 0 }}
      exit={{ opacity: 0, x: -100 }}
      transition={{ duration: 0.3, ease: EASING }}
      className="rounded-xl border border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] overflow-hidden"
    >
      {/* ═══════════ HEADER ═══════════ */}
      <div className="px-4 py-3 border-b border-gray-100 dark:border-white/5 bg-gray-50/50 dark:bg-[#1a1a1a]/50">
        <div className="flex items-center gap-2">
          {/* Drag handle */}
          <button
            className="cursor-grab active:cursor-grabbing p-0.5 text-gray-400 hover:text-gray-600 dark:hover:text-gray-300 transition-colors"
            title="Drag to reorder"
          >
            <GripVertical className="w-4 h-4" />
          </button>

          {/* Block name — editable */}
          {editingName ? (
            <input
              autoFocus
              defaultValue={block.name}
              onBlur={(e) => handleNameSave(e.target.value)}
              onKeyDown={(e) => {
                if (e.key === 'Enter') handleNameSave(e.currentTarget.value);
                if (e.key === 'Escape') setEditingName(false);
              }}
              className="flex-1 min-w-0 px-2 py-1 text-sm font-semibold rounded border border-[#00AEEF] bg-white dark:bg-[#1a1a1a] text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
            />
          ) : (
            <button
              onClick={() => setEditingName(true)}
              className="flex-1 min-w-0 text-left text-sm font-semibold text-gray-900 dark:text-white hover:text-[#00AEEF] transition-colors truncate"
            >
              {block.name}
            </button>
          )}

          {/* Format selector */}
          <div className="relative">
            <button
              onClick={() => setShowFormatMenu(!showFormatMenu)}
              className="flex items-center gap-1.5 px-2.5 py-1.5 rounded-lg text-xs font-medium bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 hover:border-[#00AEEF]/50 transition-colors"
            >
              {currentFormat && <currentFormat.icon className="w-3.5 h-3.5 text-[#00AEEF]" />}
              {currentFormat?.label ?? 'Straight'}
              <ChevronDown className="w-3 h-3 opacity-60" />
            </button>

            {/* Dropdown */}
            <AnimatePresence>
              {showFormatMenu && (
                <>
                  <div className="fixed inset-0 z-40" onClick={() => setShowFormatMenu(false)} />
                  <motion.div
                    initial={{ opacity: 0, y: -4, scale: 0.96 }}
                    animate={{ opacity: 1, y: 0, scale: 1 }}
                    exit={{ opacity: 0, y: -4, scale: 0.96 }}
                    transition={{ duration: 0.15, ease: EASING }}
                    className="absolute right-0 top-full mt-1 z-50 w-56 rounded-xl bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 shadow-lg overflow-hidden"
                  >
                    {FORMAT_OPTIONS.map((opt) => (
                      <button
                        key={opt.value}
                        onClick={() => handleFormatChange(opt.value)}
                        className={cn(
                          'w-full flex items-start gap-2.5 px-3 py-2.5 text-left transition-colors',
                          block.format === opt.value
                            ? 'bg-[#00AEEF]/10 text-[#00AEEF]'
                            : 'hover:bg-gray-50 dark:hover:bg-white/5'
                        )}
                      >
                        <opt.icon
                          className={cn(
                            'w-4 h-4 mt-0.5 shrink-0',
                            block.format === opt.value ? 'text-[#00AEEF]' : 'text-gray-400'
                          )}
                        />
                        <div>
                          <p className="text-xs font-medium text-gray-900 dark:text-white">
                            {opt.label}
                          </p>
                          <p className="text-[10px] text-gray-500 dark:text-gray-400 mt-0.5">
                            {opt.description}
                          </p>
                        </div>
                      </button>
                    ))}
                  </motion.div>
                </>
              )}
            </AnimatePresence>
          </div>

          {/* Delete */}
          <button
            onClick={onDeleteBlock}
            className="p-1.5 rounded-lg text-gray-400 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
            title="Delete block"
          >
            <X className="w-3.5 h-3.5" />
          </button>
        </div>

        {/* Format description */}
        {currentFormat && (
          <p className="mt-1.5 ml-6 text-[10px] text-gray-400 dark:text-gray-500">
            {currentFormat.description}
          </p>
        )}
      </div>

      {/* ═══════════ EXERCISE LIST ═══════════ */}
      <Reorder.Group
        axis="y"
        values={block.exercises}
        onReorder={handleReorder}
        className="divide-y divide-gray-50 dark:divide-white/[0.02]"
      >
        <AnimatePresence>
          {block.exercises.map((exercise) => (
            <Reorder.Item
              key={exercise.id}
              value={exercise}
              dragListener={false}
              className="group"
            >
              <ExerciseRow
                exercise={exercise}
                onUpdate={(data) => onUpdateExercise(exercise.id, data)}
                onRemove={() => onRemoveExercise(exercise.id)}
              />
            </Reorder.Item>
          ))}
        </AnimatePresence>
      </Reorder.Group>

      {/* Empty state */}
      {block.exercises.length === 0 && (
        <div className="px-4 py-6 text-center">
          <p className="text-xs text-gray-400 dark:text-gray-500">
            No exercises in this block yet.
          </p>
        </div>
      )}

      {/* ═══════════ FOOTER ═══════════ */}
      <div className="px-4 py-2.5 border-t border-gray-100 dark:border-white/5 bg-gray-50/30 dark:bg-[#1a1a1a]/30">
        <button
          onClick={() => setShowExercisePicker(true)}
          className="flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium text-[#00AEEF] hover:bg-[#00AEEF]/10 transition-colors"
        >
          <Plus className="w-3.5 h-3.5" />
          Add Exercise
        </button>
      </div>

      {/* ═══════════ EXERCISE PICKER ═══════════ */}
      <ExercisePicker
        open={showExercisePicker}
        onClose={() => setShowExercisePicker(false)}
        onSelectExercise={(exercise) => {
          onAddExercise({
            exerciseId: exercise.id,
            name: exercise.name,
            sets: 4,
            reps: '8-12',
            rest: '90s',
            tempo: '3010',
            notes: '',
          });
          setShowExercisePicker(false);
        }}
      />
    </motion.div>
  );
}

// ─────────────────────────────────────────────────────────────────────────────
// Exercise Row — inline editable row inside a block
// ─────────────────────────────────────────────────────────────────────────────

interface ExerciseRowProps {
  exercise: BlockExercise;
  onUpdate: (data: Partial<BlockExercise>) => void;
  onRemove: () => void;
}

function ExerciseRow({ exercise, onUpdate, onRemove }: ExerciseRowProps) {
  return (
    <motion.div
      layout="position"
      initial={{ opacity: 0 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0, x: -20 }}
      transition={{ duration: 0.2, ease: EASING }}
      className="flex items-center gap-2 px-4 py-2 text-sm hover:bg-gray-50 dark:hover:bg-white/[0.02] transition-colors group"
    >
      {/* Drag handle */}
      <div className="cursor-grab active:cursor-grabbing p-0.5 text-gray-400 opacity-0 group-hover:opacity-100 transition-opacity">
        <GripVertical className="w-3.5 h-3.5" />
      </div>

      {/* Group badge */}
      <motion.span
        key={exercise.exerciseGroup ?? ''}
        initial={{ scale: 1.2 }}
        animate={{ scale: 1 }}
        transition={{ duration: 0.25, ease: EASING }}
        className={cn(
          'shrink-0 inline-flex items-center justify-center px-1.5 py-0.5 rounded-md text-[10px] font-bold min-w-[2rem]',
          GROUP_COLORS[exercise.exerciseGroup ?? ''] ?? 'bg-gray-100 text-gray-600'
        )}
      >
        {exercise.exerciseGroup ?? ''}
      </motion.span>

      {/* Exercise name — editable */}
      <div className="flex-1 min-w-0">
        <EditCell
          value={exercise.name ?? exercise.exerciseName ?? ''}
          onSave={(val) => onUpdate({ name: val })}
          className="text-left w-full font-medium text-gray-900 dark:text-white"
          type="text"
        />
      </div>

      {/* Sets */}
      <div className="shrink-0 w-12">
        <EditCell
          value={exercise.sets}
          onSave={(val) => onUpdate({ sets: parseInt(val) || 0 })}
          type="number"
          min={1}
          max={20}
          className="w-12"
          title="Sets"
        />
      </div>

      {/* Reps */}
      <div className="shrink-0 w-16">
        <EditCell
          value={exercise.reps}
          onSave={(val) => onUpdate({ reps: val })}
          className="w-16"
          title="Reps (e.g. 8-12, 10, AMRAP)"
        />
      </div>

      {/* Tempo */}
      <div className="shrink-0 w-12">
        <EditCell
          value={exercise.tempo ?? ''}
          onSave={(val) => onUpdate({ tempo: val })}
          className="w-12"
          title="Eccentric-Pause-Concentric-Pause"
        />
      </div>

      {/* Rest */}
      <div className="shrink-0 w-12">
        <EditCell
          value={exercise.rest ?? ''}
          onSave={(val) => onUpdate({ rest: val })}
          className="w-12"
          title="Rest (e.g. 90s, 2min)"
        />
      </div>

      {/* Notes tooltip */}
      {exercise.notes && (
        <div className="shrink-0 group/note relative">
          <Info className="w-3.5 h-3.5 text-gray-400" />
          <div className="absolute right-0 bottom-full mb-1 hidden group-hover/note:block z-10 w-48 p-2 rounded-lg bg-gray-900 text-white text-xs shadow-lg">
            {exercise.notes}
          </div>
        </div>
      )}

      {/* Delete */}
      <button
        onClick={onRemove}
        className="shrink-0 p-1 rounded-md text-gray-300 hover:text-red-500 hover:bg-red-50 dark:hover:bg-red-900/20 opacity-0 group-hover:opacity-100 transition-all"
        title="Remove exercise"
      >
        <Trash2 className="w-3 h-3" />
      </button>
    </motion.div>
  );
}
