/**
 * GoalSelectionStep.tsx — Step 1 of the AzFIT Program Design Wizard
 *
 * Presents 5 goal options as horizontal cards. Each card features an icon
 * in a circle, title, description, and a chevron. Selection triggers a
 * cyan border/highlight and stores the goal in wizard state.
 */

import { motion } from 'framer-motion';
import { Flame, Dumbbell, Zap, Heart, Activity, ChevronRight, Check } from 'lucide-react';
import { useProgramStore, type GoalType } from '@/stores/useProgramStore';
import { cn } from '@/lib/utils';

/* ------------------------------------------------------------------ */
/*  GOAL CONFIGURATION                                                */
/* ------------------------------------------------------------------ */

interface GoalConfig {
  id: GoalType;
  title: string;
  description: string;
  icon: React.ElementType;
}

const GOALS: GoalConfig[] = [
  {
    id: 'lose-fat',
    title: 'Lose Weight',
    description: 'Focus on fat loss with calorie-burning workouts',
    icon: Flame,
  },
  {
    id: 'build-muscle',
    title: 'Build Muscle',
    description: 'Hypertrophy-focused training for size gains',
    icon: Dumbbell,
  },
  {
    id: 'strength',
    title: 'Improve Strength',
    description: 'Maximal strength development with lower reps',
    icon: Zap,
  },
  {
    id: 'endurance',
    title: 'Increase Endurance',
    description: 'Build stamina and work capacity',
    icon: Activity,
  },
  {
    id: 'maintenance',
    title: 'General Fitness',
    description: 'Balanced approach for overall health',
    icon: Heart,
  },
];

/* ------------------------------------------------------------------ */
/*  COMPONENT                                                         */
/* ------------------------------------------------------------------ */

export default function GoalSelectionStep() {
  const { wizard, setWizardGoal } = useProgramStore();
  const selectedGoal = wizard.selectedGoal;

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* Title */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center space-y-2"
      >
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          What&apos;s your primary goal?
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Select the main training objective
        </p>
      </motion.div>

      {/* Goal Cards */}
      <div className="space-y-3">
        {GOALS.map((goal, index) => {
          const isSelected = selectedGoal === goal.id;
          const Icon = goal.icon;

          return (
            <motion.button
              key={goal.id}
              initial={{ opacity: 0, x: -20 }}
              animate={{ opacity: 1, x: 0 }}
              transition={{ delay: index * 0.08, duration: 0.35 }}
              whileHover={{ x: 4 }}
              whileTap={{ scale: 0.98 }}
              onClick={() => setWizardGoal(goal.id)}
              className={cn(
                'w-full flex items-center gap-4 p-5 border rounded-xl cursor-pointer transition-all group text-left',
                isSelected
                  ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                  : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10'
              )}
            >
              {/* Left: Icon in circle */}
              <div
                className={cn(
                  'flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-colors',
                  isSelected
                    ? 'bg-[#00AEEF]'
                    : 'bg-cyan-50 dark:bg-cyan-950/20 group-hover:bg-[#00AEEF]'
                )}
              >
                {isSelected ? (
                  <Check className="w-5 h-5 text-white" />
                ) : (
                  <Icon
                    className={cn(
                      'w-5 h-5 text-[#00AEEF] transition-colors',
                      'group-hover:text-white'
                    )}
                  />
                )}
              </div>

              {/* Center: Title + Description */}
              <div className="flex-1 min-w-0">
                <h3 className="font-semibold text-gray-900 dark:text-white">
                  {goal.title}
                </h3>
                <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">
                  {goal.description}
                </p>
              </div>

              {/* Right: Chevron */}
              <ChevronRight
                className={cn(
                  'w-5 h-5 flex-shrink-0 transition-colors',
                  isSelected
                    ? 'text-[#00AEEF]'
                    : 'text-gray-300 dark:text-gray-600 group-hover:text-[#00AEEF]'
                )}
              />
            </motion.button>
          );
        })}
      </div>
    </div>
  );
}
