/**
 * WeeklySplitStep.tsx — Step 5 of the AzFIT Program Design Wizard
 *
 * Allows trainers to configure their client's weekly training schedule
 * with horizontal card-style day selectors and a split visualizer.
 */

import { useState } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Lightbulb,
  Clock,
  Dumbbell,
  Pencil,
  RotateCcw,
  ChevronRight,
  Moon,
  Sun,
  CalendarDays,
} from 'lucide-react';
import type { DayPlan, DayOfWeek } from '@/types/program';
import { cn } from '@/lib/utils';

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface WeeklySplitStepProps {
  /** Current weekly split configuration (passed from parent state) */
  weeklySplit: DayPlan[];
  /** Callback when user toggles a day active/inactive */
  onToggleDay: (day: DayOfWeek) => void;
  /** Callback when user wants to edit a specific day's exercises */
  onEditDay: (day: DayOfWeek) => void;
  /** Callback when user resets to the default split */
  onResetSplit: () => void;
  /** Called when user completes this step */
  onNext: () => void;
  /** Called when user wants to go back */
  onBack: () => void;
}

/** All 7 days of the week in order */
const DAYS: DayOfWeek[] = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];

/** Focus options for training days */
const FOCUS_OPTIONS = [
  'Upper Body',
  'Lower Body',
  'Push',
  'Pull',
  'Legs',
  'Full Body',
  'Chest & Back',
  'Shoulders & Arms',
  'Core & Conditioning',
];

/** Smart suggestion text for an Upper/Lower split */
const SMART_SUGGESTION = 'Optimal split: Mon Upper | Tue Lower | Thu Upper | Fri Lower';

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function WeeklySplitStep({
  weeklySplit,
  onToggleDay,
  onEditDay,
  onResetSplit,
}: WeeklySplitStepProps) {
  const [editingFocus, setEditingFocus] = useState<string | null>(null);

  /** Count total active training days */
  const activeDays = weeklySplit.filter((d) => !d.isRestDay).length;

  /** Count total exercises across all training days */
  const totalExercises = weeklySplit.reduce(
    (acc, d) => acc + d.exercises.length,
    0
  );

  /** Get the DayPlan for a specific day */
  const getDayPlan = (day: DayOfWeek): DayPlan | undefined => {
    return weeklySplit.find((d) => d.dayOfWeek === day);
  };

  /** Update focus for a day */
  const handleFocusChange = (dayOfWeek: string, newFocus: string) => {
    const plan = weeklySplit.find((d) => d.dayOfWeek === dayOfWeek);
    if (plan) {
      plan.focus = newFocus;
    }
    setEditingFocus(null);
  };

  return (
    <div className="space-y-6 max-w-2xl mx-auto">
      {/* ── Header ── */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center space-y-2"
      >
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          Choose your training days
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Select which days your client trains and assign a focus to each
        </p>
      </motion.div>

      {/* ── Smart Suggestion Banner ── */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        className="flex items-start gap-3 p-4 rounded-xl bg-gradient-to-r from-[#00AEEF]/10 to-[#22C55E]/10 border border-[#00AEEF]/20 dark:border-[#00AEEF]/20"
      >
        <Lightbulb className="w-5 h-5 text-[#00AEEF] mt-0.5 shrink-0" />
        <div>
          <p className="text-sm font-medium text-gray-800 dark:text-gray-200">
            Smart Suggestion
          </p>
          <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">
            {SMART_SUGGESTION}
          </p>
        </div>
      </motion.div>

      {/* ── Stats Bar ── */}
      <div className="flex items-center justify-center gap-6 text-sm">
        <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
          <CalendarDays className="w-4 h-4 text-[#00AEEF]" />
          <span>
            <strong className="text-gray-900 dark:text-white">{activeDays}</strong> training days
          </span>
        </div>
        <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
          <Dumbbell className="w-4 h-4 text-[#00AEEF]" />
          <span>
            <strong className="text-gray-900 dark:text-white">{totalExercises}</strong> exercises
          </span>
        </div>
        <div className="flex items-center gap-2 text-gray-600 dark:text-gray-400">
          <Clock className="w-4 h-4 text-[#00AEEF]" />
          <span>
            ~<strong className="text-gray-900 dark:text-white">{activeDays > 0 ? Math.round(weeklySplit.filter((d) => !d.isRestDay).reduce((acc, d) => acc + d.estimatedTime, 0) / activeDays) : 0}</strong> min avg
          </span>
        </div>
      </div>

      {/* ── Day Cards ── */}
      <div className="space-y-3">
        <AnimatePresence mode="popLayout">
          {DAYS.map((day, index) => {
            const plan = getDayPlan(day);
            if (!plan) return null;
            const active = !plan.isRestDay;

            return (
              <motion.div
                key={day}
                layout
                initial={{ opacity: 0, x: -20 }}
                animate={{ opacity: 1, x: 0 }}
                exit={{ opacity: 0, x: 20 }}
                transition={{ delay: index * 0.06, duration: 0.3 }}
                className={cn(
                  'flex items-center gap-4 p-4 border rounded-xl transition-all group',
                  active
                    ? 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414]'
                    : 'border-dashed border-gray-200 dark:border-white/5 bg-gray-50/50 dark:bg-[#141414]/30'
                )}
              >
                {/* Day Toggle Button */}
                <button
                  onClick={() => onToggleDay(day)}
                  className={cn(
                    'flex-shrink-0 w-12 h-12 rounded-xl font-semibold text-sm transition-all duration-200 flex items-center justify-center',
                    active
                      ? 'bg-[#00AEEF] text-white shadow-lg shadow-[#00AEEF]/25'
                      : 'bg-gray-200 dark:bg-[#1a1a1a] text-gray-400 dark:text-gray-500 hover:bg-gray-300 dark:hover:bg-[#222]'
                  )}
                  title={active ? 'Click to make rest day' : 'Click to activate training day'}
                >
                  {day}
                </button>

                {/* Day Info */}
                <div className="flex-1 min-w-0">
                  {active ? (
                    <>
                      <div className="flex items-center gap-2">
                        <Sun className="w-3.5 h-3.5 text-[#00AEEF]" />
                        <span className="font-semibold text-sm text-gray-900 dark:text-white">
                          Training Day
                        </span>
                      </div>
                      {/* Focus selector */}
                      {editingFocus === day ? (
                        <select
                          autoFocus
                          value={plan.focus}
                          onChange={(e) => handleFocusChange(day, e.target.value)}
                          onBlur={() => setEditingFocus(null)}
                          className="mt-1 text-xs bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 rounded-lg px-2 py-1 text-[#00AEEF] focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
                        >
                          {FOCUS_OPTIONS.map((opt) => (
                            <option key={opt} value={opt}>{opt}</option>
                          ))}
                        </select>
                      ) : (
                        <button
                          onClick={() => setEditingFocus(day)}
                          className="mt-1 text-xs text-[#00AEEF] hover:underline flex items-center gap-1"
                        >
                          {plan.focus}
                          <Pencil className="w-3 h-3" />
                        </button>
                      )}
                    </>
                  ) : (
                    <>
                      <div className="flex items-center gap-2">
                        <Moon className="w-3.5 h-3.5 text-gray-400" />
                        <span className="font-medium text-sm text-gray-500 dark:text-gray-400">
                          Rest Day
                        </span>
                      </div>
                      <p className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                        Active recovery optional
                      </p>
                    </>
                  )}
                </div>

                {/* Right side: Exercise count or toggle */}
                {active ? (
                  <div className="flex items-center gap-3">
                    <div className="text-right">
                      <div className="flex items-center gap-1 text-xs text-gray-500 dark:text-gray-400">
                        <Clock className="w-3 h-3" />
                        {plan.estimatedTime} min
                      </div>
                      <div className="text-xs text-gray-400 dark:text-gray-500 mt-0.5">
                        {plan.exercises.length} exercises
                      </div>
                    </div>
                    <button
                      onClick={() => onEditDay(day)}
                      className="flex items-center gap-1 text-xs font-medium text-[#00AEEF] hover:text-[#0095CC] transition-colors px-2 py-1 rounded-lg hover:bg-[#00AEEF]/10"
                    >
                      Edit
                      <ChevronRight className="w-3 h-3" />
                    </button>
                  </div>
                ) : (
                  <button
                    onClick={() => onToggleDay(day)}
                    className="text-xs text-[#00AEEF] hover:text-[#0095CC] transition-colors px-3 py-1.5 rounded-lg hover:bg-[#00AEEF]/10"
                  >
                    Activate
                  </button>
                )}
              </motion.div>
            );
          })}
        </AnimatePresence>
      </div>

      {/* ── Reset ── */}
      <div className="flex items-center justify-center">
        <button
          onClick={onResetSplit}
          className="flex items-center gap-2 text-sm text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-200 transition-colors"
        >
          <RotateCcw className="w-4 h-4" />
          Reset to Default Split
        </button>
      </div>
    </div>
  );
}
