/**
 * AzFIT Program Design Wizard — Step 7: Program Preview
 *
 * Provides a comprehensive overview of the program before saving.
 * Includes summary statistics, volume analysis, equipment checklist,
 * time estimates, safety summary, and a week-by-week breakdown view.
 */

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Calendar,
  CheckCircle,
  ChevronLeft,
  ChevronRight,
  Clock,
  Dumbbell,
  FileText,
  Layers,
  Shield,
  ShieldCheck,
  Timer,
  TrendingUp,
  XCircle,
  Zap,
} from 'lucide-react';
import type { Program, DayPlan, ProgramExercise, ProgramPhase } from '@/types/program';
import { calculateMuscleDistribution, getGoalLabel, getGoalColor, getDifficultyColor } from '@/lib/program-data';

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface ProgramPreviewStepProps {
  /** The complete program to preview */
  program: Program;
  /** Called when user completes this step */
  onNext: () => void;
  /** Called when user wants to go back */
  onBack: () => void;
}

/** Color mapping for muscle group mini bars */
const MUSCLE_COLORS: Record<string, string> = {
  Chest: 'bg-red-400',
  Back: 'bg-blue-400',
  Legs: 'bg-emerald-400',
  Shoulders: 'bg-purple-400',
  Arms: 'bg-orange-400',
  Core: 'bg-yellow-400',
};

/** Mock available equipment for the checklist */
const AVAILABLE_EQUIPMENT = [
  'Barbell',
  'Dumbbell',
  'Cable Machine',
  'Pull-up Bar',
  'Dip Station',
  'Leg Press Machine',
  'Bench',
  'Squat Rack',
];

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function ProgramPreviewStep({ program, onNext, onBack }: ProgramPreviewStepProps) {
  /** View toggle: 'summary' or 'week-by-week' */
  const [view, setView] = useState<'summary' | 'week-by-week'>('summary');

  /** Total number of training sessions */
  const totalSessions = useMemo(() => {
    const trainingDays = program.weeklySplit.filter((d: DayPlan) => !d.isRestDay).length;
    return trainingDays * program.duration;
  }, [program.weeklySplit, program.duration]);

  /** Total sets per week */
  const totalSetsPerWeek = useMemo(() => {
    return program.weeklySplit.reduce(
      (acc: number, day: DayPlan) =>
        acc + day.exercises.reduce((dAcc: number, ex: ProgramExercise) => dAcc + ex.sets, 0),
      0
    );
  }, [program.weeklySplit]);

  /** Estimated total reps per week (sets × avg reps) */
  const estimatedRepsPerWeek = useMemo(() => {
    return program.weeklySplit.reduce((acc: number, day: DayPlan) => {
      return (
        acc +
        day.exercises.reduce((dAcc: number, ex: ProgramExercise) => {
          // Parse rep ranges like "8-10" or "12" or "45s"
          const repStr = ex.reps;
          if (repStr.includes('s')) return dAcc + ex.sets * 1; // Time-based = 1 per set
          if (repStr.includes('each')) {
            const num = parseInt(repStr);
            return dAcc + ex.sets * (isNaN(num) ? 10 : num) * 2;
          }
          if (repStr.includes('-')) {
            const [min, max] = repStr.split('-').map((n) => parseInt(n));
            return dAcc + ex.sets * ((min + max) / 2);
          }
          const num = parseInt(repStr);
          return dAcc + ex.sets * (isNaN(num) ? 10 : num);
        }, 0)
      );
    }, 0);
  }, [program.weeklySplit]);

  /** Muscle group distribution */
  const allExercises = useMemo(
    () => program.weeklySplit.flatMap((d: DayPlan) => d.exercises),
    [program.weeklySplit]
  );
  const muscleDistribution = useMemo(
    () => calculateMuscleDistribution(allExercises),
    [allExercises]
  );

  /** Equipment checklist: which required items are available */
  const equipmentChecklist = useMemo(() => {
    return program.equipmentRequired.map((eq: string) => ({
      name: eq,
      available: AVAILABLE_EQUIPMENT.includes(eq),
    }));
  }, [program.equipmentRequired]);

  /** Safety summary stats */
  const adjustedCount = useMemo(
    () => allExercises.filter((e: ProgramExercise) => e.isSubstituted).length,
    [allExercises]
  );

  const supersetCount = useMemo(() => {
    const pairs = new Set<string>();
    allExercises.forEach((e: ProgramExercise) => {
      if (e.supersetWith) {
        const pair = [e.exerciseId, e.supersetWith].sort().join('-');
        pairs.add(pair);
      }
    });
    return pairs.size;
  }, [allExercises]);

  /** Day time estimates */
  const dayEstimates = useMemo(
    () =>
      program.weeklySplit
        .filter((d: DayPlan) => !d.isRestDay)
        .map((d: DayPlan) => ({
          day: d.dayOfWeek,
          focus: d.focus,
          time: d.estimatedTime,
          exercises: d.exercises.length,
        })),
    [program.weeklySplit]
  );

  return (
    <div className="space-y-6">
      {/* ── Header ── */}
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">Program Preview</h2>
        <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm">
          Review your program before saving and assigning
        </p>
      </div>

      {/* ── View Toggle ── */}
      <div className="flex items-center justify-center">
        <div className="inline-flex p-1 rounded-xl bg-gray-100 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/5">
          <button
            onClick={() => setView('summary')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
              view === 'summary'
                ? 'bg-white dark:bg-[#222] text-[#00AEEF] shadow-sm'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <FileText className="w-4 h-4 inline mr-1.5 -mt-0.5" />
            Summary
          </button>
          <button
            onClick={() => setView('week-by-week')}
            className={`px-4 py-2 rounded-lg text-sm font-medium transition-all duration-200 ${
              view === 'week-by-week'
                ? 'bg-white dark:bg-[#222] text-[#00AEEF] shadow-sm'
                : 'text-gray-500 dark:text-gray-400 hover:text-gray-700 dark:hover:text-gray-300'
            }`}
          >
            <Layers className="w-4 h-4 inline mr-1.5 -mt-0.5" />
            Week-by-Week
          </button>
        </div>
      </div>

      {/* ── Summary View ── */}
      <AnimatePresence mode="wait">
        {view === 'summary' ? (
          <motion.div
            key="summary"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-6"
          >
            {/* Program Card */}
            <div className="p-6 rounded-2xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10 shadow-sm">
              <div className="flex items-start justify-between">
                <div>
                  <h3 className="text-xl font-bold text-gray-900 dark:text-white">
                    {program.name}
                  </h3>
                  <p className="text-sm text-gray-500 dark:text-gray-400 mt-1 max-w-lg">
                    {program.description}
                  </p>
                  <div className="flex items-center gap-2 mt-3 flex-wrap">
                    {/* Goal badge */}
                    <span
                      className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${getGoalColor(
                        program.goal
                      )}`}
                    >
                      {getGoalLabel(program.goal)}
                    </span>
                    {/* Difficulty badge */}
                    <span
                      className={`px-2.5 py-0.5 rounded-full text-xs font-medium ${getDifficultyColor(
                        program.difficulty
                      )}`}
                    >
                      {program.difficulty.charAt(0).toUpperCase() + program.difficulty.slice(1)}
                    </span>
                    {/* Method */}
                    <span className="px-2.5 py-0.5 rounded-full text-xs font-medium bg-gray-100 text-gray-600 dark:bg-[#1a1a1a] dark:text-gray-400">
                      {program.method}
                    </span>
                  </div>
                </div>
                <div className="text-right shrink-0">
                  <div className="text-3xl font-bold text-[#00AEEF]">{program.duration}</div>
                  <div className="text-xs text-gray-500 dark:text-gray-400">weeks</div>
                </div>
              </div>

              {/* Quick stats grid */}
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4 mt-6 pt-6 border-t border-gray-100 dark:border-white/5">
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1.5 text-gray-400 mb-1">
                    <Calendar className="w-4 h-4" />
                    <span className="text-xs">Frequency</span>
                  </div>
                  <div className="text-lg font-bold text-gray-900 dark:text-white">
                    {program.frequency}x
                  </div>
                  <div className="text-[10px] text-gray-400">per week</div>
                </div>
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1.5 text-gray-400 mb-1">
                    <Layers className="w-4 h-4" />
                    <span className="text-xs">Sessions</span>
                  </div>
                  <div className="text-lg font-bold text-gray-900 dark:text-white">
                    {totalSessions}
                  </div>
                  <div className="text-[10px] text-gray-400">total</div>
                </div>
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1.5 text-gray-400 mb-1">
                    <Timer className="w-4 h-4" />
                    <span className="text-xs">Avg Time</span>
                  </div>
                  <div className="text-lg font-bold text-gray-900 dark:text-white">
                    {program.estimatedTimePerSession}m
                  </div>
                  <div className="text-[10px] text-gray-400">per session</div>
                </div>
                <div className="text-center">
                  <div className="flex items-center justify-center gap-1.5 text-gray-400 mb-1">
                    <Dumbbell className="w-4 h-4" />
                    <span className="text-xs">Volume</span>
                  </div>
                  <div className="text-lg font-bold text-gray-900 dark:text-white">
                    {program.totalVolume}
                  </div>
                  <div className="text-[10px] text-gray-400">sets/week</div>
                </div>
              </div>
            </div>

            {/* Volume Summary & Muscle Distribution */}
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {/* Volume Summary */}
              <div className="p-5 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10">
                <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-200 mb-4 flex items-center gap-2">
                  <TrendingUp className="w-4 h-4 text-[#00AEEF]" />
                  Volume Summary
                </h4>
                <div className="space-y-3">
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Total Sets / Week</span>
                    <span className="text-sm font-bold text-gray-900 dark:text-white">
                      {totalSetsPerWeek}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Est. Total Reps / Week</span>
                    <span className="text-sm font-bold text-gray-900 dark:text-white">
                      {Math.round(estimatedRepsPerWeek).toLocaleString()}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Avg Sets per Exercise</span>
                    <span className="text-sm font-bold text-gray-900 dark:text-white">
                      {allExercises.length
                        ? (totalSetsPerWeek / allExercises.length).toFixed(1)
                        : 0}
                    </span>
                  </div>
                  <div className="flex items-center justify-between">
                    <span className="text-sm text-gray-600 dark:text-gray-400">Exercises per Session</span>
                    <span className="text-sm font-bold text-gray-900 dark:text-white">
                      {program.weeklySplit.filter((d: DayPlan) => !d.isRestDay).length
                        ? (
                            allExercises.length /
                            program.weeklySplit.filter((d: DayPlan) => !d.isRestDay).length
                          ).toFixed(1)
                        : 0}
                    </span>
                  </div>
                </div>
              </div>

              {/* Muscle Distribution Mini Chart */}
              <div className="p-5 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10">
                <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-200 mb-4">
                  Muscle Distribution
                </h4>
                {/* Horizontal bar chart */}
                <div className="space-y-2.5">
                  {muscleDistribution.map((m) => (
                    <div key={m.muscleGroup}>
                      <div className="flex items-center justify-between mb-1">
                        <span className="text-xs text-gray-600 dark:text-gray-400">
                          {m.muscleGroup}
                        </span>
                        <span className="text-xs font-medium text-gray-800 dark:text-gray-300">
                          {m.percentage}%
                        </span>
                      </div>
                      <div className="h-2 rounded-full bg-gray-100 dark:bg-[#1a1a1a] overflow-hidden">
                        <motion.div
                          initial={{ width: 0 }}
                          animate={{ width: `${m.percentage}%` }}
                          transition={{ duration: 0.6, ease: 'easeOut' }}
                          className={`h-full rounded-full ${MUSCLE_COLORS[m.muscleGroup] || 'bg-gray-400'}`}
                        />
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>

            {/* Equipment Checklist */}
            <div className="p-5 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10">
              <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-200 mb-4 flex items-center gap-2">
                <Dumbbell className="w-4 h-4 text-[#00AEEF]" />
                Equipment Checklist
              </h4>
              <div className="grid grid-cols-2 sm:grid-cols-3 md:grid-cols-4 gap-3">
                {equipmentChecklist.map((eq) => (
                  <div
                    key={eq.name}
                    className={`flex items-center gap-2 p-2.5 rounded-lg ${
                      eq.available
                        ? 'bg-green-50 dark:bg-green-900/20'
                        : 'bg-red-50 dark:bg-red-900/20'
                    }`}
                  >
                    {eq.available ? (
                      <CheckCircle className="w-4 h-4 text-[#22C55E] shrink-0" />
                    ) : (
                      <XCircle className="w-4 h-4 text-red-500 shrink-0" />
                    )}
                    <span
                      className={`text-xs font-medium ${
                        eq.available
                          ? 'text-green-700 dark:text-green-400'
                          : 'text-red-700 dark:text-red-400'
                      }`}
                    >
                      {eq.name}
                    </span>
                  </div>
                ))}
              </div>
            </div>

            {/* Time Estimates per Day */}
            <div className="p-5 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10">
              <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-200 mb-4 flex items-center gap-2">
                <Clock className="w-4 h-4 text-[#00AEEF]" />
                Time Estimates per Day
              </h4>
              <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
                {dayEstimates.map((d) => (
                  <div
                    key={d.day}
                    className="p-3 rounded-lg bg-gray-50 dark:bg-[#1a1a1a] border border-gray-100 dark:border-white/5"
                  >
                    <div className="flex items-center gap-2 mb-1">
                      <span className="text-xs font-bold text-[#00AEEF]">{d.day}</span>
                      <Clock className="w-3 h-3 text-gray-400" />
                    </div>
                    <div className="text-lg font-bold text-gray-900 dark:text-white">
                      {d.time}m
                    </div>
                    <div className="text-[10px] text-gray-400 truncate">{d.focus}</div>
                  </div>
                ))}
              </div>
            </div>

            {/* Safety Summary */}
            <div className="p-5 rounded-xl bg-gradient-to-r from-amber-50 to-orange-50 dark:from-amber-900/20 dark:to-orange-900/20 border border-amber-200 dark:border-amber-800/30">
              <h4 className="text-sm font-semibold text-gray-800 dark:text-gray-200 mb-3 flex items-center gap-2">
                <Shield className="w-4 h-4 text-amber-600 dark:text-amber-400" />
                Safety Summary
              </h4>
              <div className="grid grid-cols-2 sm:grid-cols-3 gap-3">
                <div className="flex items-center gap-2">
                  <CheckCircle className="w-4 h-4 text-[#22C55E]" />
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                      {adjustedCount}
                    </div>
                    <div className="text-[10px] text-gray-500 dark:text-gray-400">
                      exercises adjusted
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <Zap className="w-4 h-4 text-[#00AEEF]" />
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                      {supersetCount}
                    </div>
                    <div className="text-[10px] text-gray-500 dark:text-gray-400">
                      supersets configured
                    </div>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <ShieldCheck className="w-4 h-4 text-[#22C55E]" />
                  <div>
                    <div className="text-sm font-medium text-gray-900 dark:text-white">
                      {program.progressionRules.length}
                    </div>
                    <div className="text-[10px] text-gray-500 dark:text-gray-400">
                      progression rules
                    </div>
                  </div>
                </div>
              </div>
            </div>
          </motion.div>
        ) : (
          /* ── Week-by-Week View ── */
          <motion.div
            key="week-by-week"
            initial={{ opacity: 0, y: 10 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: -10 }}
            className="space-y-4"
          >
            {Array.from({ length: program.duration }, (_, weekIndex) => {
              const weekNum = weekIndex + 1;
              const phase = program.phases.find(
                (p: ProgramPhase) => weekNum >= p.weekStart && weekNum <= p.weekEnd
              );

              return (
                <div
                  key={weekNum}
                  className="p-5 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10"
                >
                  {/* Week header */}
                  <div className="flex items-center justify-between mb-4">
                    <div className="flex items-center gap-3">
                      <div className="w-8 h-8 rounded-lg bg-[#00AEEF]/10 flex items-center justify-center">
                        <span className="text-xs font-bold text-[#00AEEF]">W{weekNum}</span>
                      </div>
                      <div>
                        <h4 className="text-sm font-semibold text-gray-900 dark:text-white">
                          Week {weekNum}
                        </h4>
                        {phase && (
                          <p className="text-xs text-gray-500 dark:text-gray-400">
                            {phase.name} — {phase.focus}
                          </p>
                        )}
                      </div>
                    </div>
                    {phase && (
                      <span className="px-2 py-0.5 rounded-full text-[10px] font-medium bg-gray-100 text-gray-500 dark:bg-[#1a1a1a] dark:text-gray-400">
                        {phase.intensityTarget}
                      </span>
                    )}
                  </div>

                  {/* Days */}
                  <div className="space-y-2">
                    {program.weeklySplit.map((day: DayPlan) => (
                      <div
                        key={`${weekNum}-${day.dayOfWeek}`}
                        className={`p-3 rounded-lg ${
                          day.isRestDay
                            ? 'bg-gray-50 dark:bg-[#1a1a1a]/50 border border-dashed border-gray-200 dark:border-white/5'
                            : 'bg-gray-50 dark:bg-[#1a1a1a] border border-gray-100 dark:border-white/5'
                        }`}
                      >
                        <div className="flex items-center justify-between">
                          <div className="flex items-center gap-2">
                            <span className="text-xs font-bold text-gray-500 dark:text-gray-400 w-8">
                              {day.dayOfWeek}
                            </span>
                            {day.isRestDay ? (
                              <span className="text-xs text-gray-400 dark:text-gray-500 italic">
                                Rest Day
                              </span>
                            ) : (
                              <span className="text-xs text-gray-600 dark:text-gray-400">
                                {day.focus}
                              </span>
                            )}
                          </div>
                          {!day.isRestDay && (
                            <div className="flex items-center gap-3">
                              <span className="text-[10px] text-gray-400">
                                {day.exercises.length} exercises
                              </span>
                              <span className="text-[10px] text-gray-400 flex items-center gap-1">
                                <Clock className="w-3 h-3" />
                                {day.estimatedTime}m
                              </span>
                            </div>
                          )}
                        </div>

                        {/* Exercise list for training days */}
                        {!day.isRestDay && day.exercises.length > 0 && (
                          <div className="mt-2 pt-2 border-t border-gray-200 dark:border-white/5 grid grid-cols-1 sm:grid-cols-2 gap-1">
                            {day.exercises.map((ex: ProgramExercise) => (
                              <div
                                key={ex.exerciseId}
                                className="flex items-center gap-2 text-[11px]"
                              >
                                <span className="text-gray-400 w-4">{ex.order}</span>
                                <span className="text-gray-700 dark:text-gray-300 truncate">
                                  {ex.name}
                                </span>
                                <span className="text-gray-400 ml-auto shrink-0">
                                  {ex.sets}×{ex.reps}
                                </span>
                              </div>
                            ))}
                          </div>
                        )}
                      </div>
                    ))}
                  </div>
                </div>
              );
            })}
          </motion.div>
        )}
      </AnimatePresence>

      {/* ── Navigation ── */}
      <div className="flex items-center justify-between pt-6 border-t border-gray-100 dark:border-white/5">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors"
        >
          <ChevronLeft className="w-4 h-4" />
          Back
        </button>
        <button
          onClick={onNext}
          className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-semibold bg-[#00AEEF] text-white hover:bg-[#0095CC] shadow-lg shadow-[#00AEEF]/25 transition-all duration-200"
        >
          Continue to Save
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>
    </div>
  );
}
