/**
 * ClientContextStep.tsx — Step 3 of the AzFIT Program Design Wizard
 *
 * Performs client compatibility checks when a target client is pre-selected
 * via URL parameter (?client=c1). Displays:
 *   - Compact client profile card
 *   - Equipment availability vs. required comparison
 *   - Training day availability
 *   - Safety / pain-injury warnings with suggested alternatives
 *   - Strength benchmark prerequisites
 *
 * If no client is selected, the step auto-skips with a message.
 */

import { useState, useMemo } from 'react';
import { motion } from 'framer-motion';
import {
  User, Check, X, AlertTriangle, Dumbbell, Calendar,
  Shield, TrendingUp, ChevronRight, Clock,
  GraduationCap, Home
} from 'lucide-react';
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import { useProgramStore, type DifficultyLevel } from '@/stores/useProgramStore';
import { useClientStore } from '@/stores/useClientStore';
import { cn } from '@/lib/utils';

/* ------------------------------------------------------------------ */
/*  MOCK CLIENT CONTEXT DATA                                          */
/* ------------------------------------------------------------------ */

/** Mock available equipment per client */
const MOCK_CLIENT_EQUIPMENT: Record<string, string[]> = {
  'c1': ['Barbell', 'Dumbbells', 'Squat Rack', 'Bench', 'Cable', 'Machine'],
  'c2': ['Dumbbells', 'Cable', 'Bodyweight', 'Kettlebell'],
  'c3': ['Barbell', 'Dumbbells', 'Bodyweight'],
};

/** Mock available days per client */
const MOCK_CLIENT_DAYS: Record<string, string[]> = {
  'c1': ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'],
  'c2': ['Mon', 'Wed', 'Fri', 'Sat'],
  'c3': ['Tue', 'Thu', 'Sat', 'Sun'],
};

/** Mock injury/pain log per client */
interface PainEntry {
  bodyPart: string;
  severity: 'mild' | 'moderate' | 'severe';
  since: string;
  exercisesToAvoid: string[];
  alternatives: string[];
}

const MOCK_CLIENT_PAIN: Record<string, PainEntry[]> = {
  'c1': [
    { bodyPart: 'Left Shoulder', severity: 'mild', since: '2025-04-01', exercisesToAvoid: ['Overhead Press', 'Bench Press (heavy)'], alternatives: ['Landmine Press', 'Floor Press', 'Cable Flye'] },
  ],
  'c2': [],
  'c3': [
    { bodyPart: 'Lower Back', severity: 'moderate', since: '2025-03-15', exercisesToAvoid: ['Conventional Deadlift', 'Barbell Back Squat'], alternatives: ['Romanian Deadlift (light)', 'Goblet Squat', 'Leg Press'] },
  ],
};

/** Mock strength benchmarks per client (bodyweight ratios) */
interface Benchmark {
  exercise: string;
  target: string;
  current: string;
  status: 'passed' | 'close' | 'failed';
}

const MOCK_BENCHMARKS: Record<string, Benchmark[]> = {
  'c1': [
    { exercise: 'Squat', target: '1.5x BW', current: '1.6x BW', status: 'passed' },
    { exercise: 'Bench Press', target: '1.0x BW', current: '0.9x BW', status: 'close' },
    { exercise: 'Deadlift', target: '2.0x BW', current: '1.8x BW', status: 'close' },
  ],
  'c2': [
    { exercise: 'Squat', target: '1.5x BW', current: '1.1x BW', status: 'failed' },
    { exercise: 'Bench Press', target: '1.0x BW', current: '0.7x BW', status: 'failed' },
    { exercise: 'Deadlift', target: '2.0x BW', current: '1.3x BW', status: 'failed' },
  ],
  'c3': [
    { exercise: 'Squat', target: '1.5x BW', current: '1.4x BW', status: 'close' },
    { exercise: 'Bench Press', target: '1.0x BW', current: '1.1x BW', status: 'passed' },
    { exercise: 'Deadlift', target: '2.0x BW', current: '2.1x BW', status: 'passed' },
  ],
};

/* ------------------------------------------------------------------ */
/*  SELECTION CONFIG                                                   */
/* ------------------------------------------------------------------ */

const EXPERIENCE_LEVELS: { value: DifficultyLevel; label: string; description: string; icon: React.ElementType }[] = [
  { value: 'beginner', label: 'Beginner', description: 'New to structured training', icon: GraduationCap },
  { value: 'intermediate', label: 'Intermediate', description: '6+ months consistent training', icon: TrendingUp },
  { value: 'advanced', label: 'Advanced', description: '2+ years, high work capacity', icon: Shield },
];

const EQUIPMENT_OPTIONS: { value: string; label: string; description: string; icon: React.ElementType }[] = [
  { value: 'full-gym', label: 'Full Gym', description: 'Barbell, dumbbells, machines, cables', icon: Dumbbell },
  { value: 'dumbbells', label: 'Dumbbells Only', description: 'Adjustable dumbbells and bench', icon: Dumbbell },
  { value: 'bodyweight', label: 'Bodyweight', description: 'No equipment needed', icon: Home },
  { value: 'minimal', label: 'Minimal', description: 'Resistance bands and floor space', icon: Home },
];

const TIME_OPTIONS: { value: number; label: string; description: string }[] = [
  { value: 30, label: '30 min', description: 'Express sessions' },
  { value: 45, label: '45 min', description: 'Standard length' },
  { value: 60, label: '60 min', description: 'Full sessions' },
  { value: 90, label: '90 min', description: 'Extended training' },
];

/* ------------------------------------------------------------------ */
/*  COMPONENT                                                          */
/* ------------------------------------------------------------------ */

export default function ClientContextStep() {
  const { wizard, setWizardStep } = useProgramStore();
  const { clients } = useClientStore();
  const { selectedMethod } = wizard;

  // Local selections
  const [experienceLevel, setExperienceLevel] = useState<DifficultyLevel | null>(null);
  const [equipment, setEquipment] = useState<string | null>(null);
  const [timePerSession, setTimePerSession] = useState<number | null>(null);

  // Resolve target client from wizard state
  const targetClientId = wizard.targetClientId;

  // Find the client in the store or use fallback mock data
  const clientProfile = useMemo(() => {
    if (!targetClientId) return null;
    return clients.find((c) => c.id === targetClientId) ?? {
      id: targetClientId,
      name: 'Demo Client',
      email: 'client@example.com',
      avatar: undefined,
      status: 'active' as const,
      program: 'None',
      progress: 75,
      joinDate: '2025-01-15',
      lastSession: '2025-05-10',
    };
  }, [targetClientId, clients]);

  // Get selected method definition for equipment comparison
  const { methods } = useProgramStore();
  const methodDef = methods.find((m) => m.id === selectedMethod);

  // Equipment comparison
  const equipmentComparison = useMemo(() => {
    if (!methodDef || !targetClientId) return [];
    const required = methodDef.equipment;
    const available = MOCK_CLIENT_EQUIPMENT[targetClientId] ?? MOCK_CLIENT_EQUIPMENT['c1'];
    return required.map((eq) => ({
      name: eq,
      available: available.some((a) => a.toLowerCase() === eq.toLowerCase()),
    }));
  }, [methodDef, targetClientId]);

  // Day availability comparison
  const dayComparison = useMemo(() => {
    if (!methodDef || !targetClientId) return [];
    const requiredDays = methodDef.frequency;
    const availableDays = MOCK_CLIENT_DAYS[targetClientId] ?? MOCK_CLIENT_DAYS['c1'];
    const allDays = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
    return allDays.map((day) => ({
      day,
      available: availableDays.includes(day),
      isRequired: availableDays.indexOf(day) < requiredDays,
    }));
  }, [methodDef, targetClientId]);

  // Pain/injury data
  const painEntries = useMemo(() => {
    if (!targetClientId) return [];
    return MOCK_CLIENT_PAIN[targetClientId] ?? [];
  }, [targetClientId]);

  // Benchmark data
  const benchmarks = useMemo(() => {
    if (!targetClientId) return [];
    return MOCK_BENCHMARKS[targetClientId] ?? [];
  }, [targetClientId]);

  // Severity color mapping
  const severityColor = (s: PainEntry['severity']) => {
    switch (s) {
      case 'mild': return 'text-amber-500 bg-amber-50 dark:bg-amber-900/20 border-amber-200 dark:border-amber-800';
      case 'moderate': return 'text-orange-500 bg-orange-50 dark:bg-orange-900/20 border-orange-200 dark:border-orange-800';
      case 'severe': return 'text-red-500 bg-red-50 dark:bg-red-900/20 border-red-200 dark:border-red-800';
    }
  };

  const benchmarkColor = (s: Benchmark['status']) => {
    switch (s) {
      case 'passed': return 'text-[#22C55E]';
      case 'close': return 'text-amber-500';
      case 'failed': return 'text-red-500';
    }
  };

  const benchmarkBg = (s: Benchmark['status']) => {
    switch (s) {
      case 'passed': return 'bg-[#22C55E]/10 dark:bg-[#22C55E]/20';
      case 'close': return 'bg-amber-50 dark:bg-amber-900/20';
      case 'failed': return 'bg-red-50 dark:bg-red-900/20';
    }
  };

  /* ---- No client selected: show context selections + skip message ---- */
  if (!clientProfile) {
    return (
      <motion.div
        initial={{ opacity: 0, y: 20 }}
        animate={{ opacity: 1, y: 0 }}
        className="space-y-8 max-w-2xl mx-auto"
      >
        {/* Title */}
        <div className="text-center space-y-2">
          <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
            Tell us about your client
          </h2>
          <p className="text-sm text-gray-500 dark:text-gray-400">
            These details help tailor the program recommendations
          </p>
        </div>

        {/* Experience Level */}
        <div className="space-y-3">
          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
            Experience Level
          </p>
          <div className="space-y-3">
            {EXPERIENCE_LEVELS.map((level, index) => {
              const isSelected = experienceLevel === level.value;
              const Icon = level.icon;
              return (
                <motion.button
                  key={level.value}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: index * 0.08, duration: 0.35 }}
                  whileHover={{ x: 4 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => setExperienceLevel(level.value)}
                  className={cn(
                    'w-full flex items-center gap-4 p-5 border rounded-xl cursor-pointer transition-all group text-left',
                    isSelected
                      ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                      : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10'
                  )}
                >
                  <div className={cn(
                    'flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-colors',
                    isSelected ? 'bg-[#00AEEF]' : 'bg-cyan-50 dark:bg-cyan-950/20 group-hover:bg-[#00AEEF]'
                  )}>
                    {isSelected ? <Check className="w-5 h-5 text-white" /> : <Icon className="w-5 h-5 text-[#00AEEF] group-hover:text-white" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold text-gray-900 dark:text-white">{level.label}</h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">{level.description}</p>
                  </div>
                  <ChevronRight className={cn('w-5 h-5 flex-shrink-0 transition-colors', isSelected ? 'text-[#00AEEF]' : 'text-gray-300 dark:text-gray-600 group-hover:text-[#00AEEF]')} />
                </motion.button>
              );
            })}
          </div>
        </div>

        {/* Available Equipment */}
        <div className="space-y-3">
          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
            Available Equipment
          </p>
          <div className="space-y-3">
            {EQUIPMENT_OPTIONS.map((option, index) => {
              const isSelected = equipment === option.value;
              const Icon = option.icon;
              return (
                <motion.button
                  key={option.value}
                  initial={{ opacity: 0, x: -20 }}
                  animate={{ opacity: 1, x: 0 }}
                  transition={{ delay: 0.1 + index * 0.08, duration: 0.35 }}
                  whileHover={{ x: 4 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => setEquipment(option.value)}
                  className={cn(
                    'w-full flex items-center gap-4 p-5 border rounded-xl cursor-pointer transition-all group text-left',
                    isSelected
                      ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                      : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30 dark:hover:bg-cyan-950/10'
                  )}
                >
                  <div className={cn(
                    'flex-shrink-0 w-12 h-12 rounded-full flex items-center justify-center transition-colors',
                    isSelected ? 'bg-[#00AEEF]' : 'bg-cyan-50 dark:bg-cyan-950/20 group-hover:bg-[#00AEEF]'
                  )}>
                    {isSelected ? <Check className="w-5 h-5 text-white" /> : <Icon className="w-5 h-5 text-[#00AEEF] group-hover:text-white" />}
                  </div>
                  <div className="flex-1 min-w-0">
                    <h3 className="font-semibold text-gray-900 dark:text-white">{option.label}</h3>
                    <p className="text-sm text-gray-500 dark:text-gray-400 mt-0.5">{option.description}</p>
                  </div>
                  <ChevronRight className={cn('w-5 h-5 flex-shrink-0 transition-colors', isSelected ? 'text-[#00AEEF]' : 'text-gray-300 dark:text-gray-600 group-hover:text-[#00AEEF]')} />
                </motion.button>
              );
            })}
          </div>
        </div>

        {/* Time Per Session */}
        <div className="space-y-3">
          <p className="text-xs font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider">
            Time Per Session
          </p>
          <div className="grid grid-cols-2 gap-3">
            {TIME_OPTIONS.map((option, index) => {
              const isSelected = timePerSession === option.value;
              return (
                <motion.button
                  key={option.value}
                  initial={{ opacity: 0, y: 10 }}
                  animate={{ opacity: 1, y: 0 }}
                  transition={{ delay: 0.2 + index * 0.08, duration: 0.35 }}
                  whileHover={{ y: -2 }}
                  whileTap={{ scale: 0.98 }}
                  onClick={() => setTimePerSession(option.value)}
                  className={cn(
                    'flex items-center gap-3 p-4 border rounded-xl cursor-pointer transition-all text-left',
                    isSelected
                      ? 'border-[#00AEEF] bg-cyan-50 dark:bg-cyan-950/20 ring-2 ring-[#00AEEF]'
                      : 'border-gray-200 dark:border-white/10 bg-white dark:bg-[#141414] hover:border-[#00AEEF] hover:bg-cyan-50/30'
                  )}
                >
                  <Clock className={cn('w-5 h-5 flex-shrink-0', isSelected ? 'text-[#00AEEF]' : 'text-gray-400')} />
                  <div>
                    <h3 className="font-semibold text-gray-900 dark:text-white text-sm">{option.label}</h3>
                    <p className="text-xs text-gray-500 dark:text-gray-400">{option.description}</p>
                  </div>
                </motion.button>
              );
            })}
          </div>
        </div>

        {/* Skip Option */}
        <div className="flex flex-col items-center py-4 text-center space-y-3">
          <p className="text-sm text-gray-500 dark:text-gray-400">
            Or continue without selecting a client context
          </p>
          <Button
            variant="outline"
            size="sm"
            onClick={() => setWizardStep(4)}
            className="gap-1.5 text-[#00AEEF] border-[#00AEEF]/30 hover:bg-[#00AEEF]/5"
          >
            Skip to Phase Configuration
            <ChevronRight className="w-4 h-4" />
          </Button>
        </div>
      </motion.div>
    );
  }

  /* ---- Client context view ---- */
  return (
    <div className="space-y-6 max-w-4xl mx-auto">
      {/* Header */}
      <motion.div
        initial={{ opacity: 0, y: -10 }}
        animate={{ opacity: 1, y: 0 }}
        className="text-center space-y-2"
      >
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          Tell us about your client
        </h2>
        <p className="text-sm text-gray-500 dark:text-gray-400">
          Verifying compatibility for <span className="font-medium text-[#00AEEF]">{clientProfile.name}</span>
        </p>
      </motion.div>

      {/* Client Profile Card */}
      <motion.div
        initial={{ opacity: 0, y: 10 }}
        animate={{ opacity: 1, y: 0 }}
        transition={{ delay: 0.1 }}
        className="flex items-center gap-4 p-4 rounded-2xl bg-gradient-to-r from-[#00AEEF]/5 to-transparent border border-[#00AEEF]/15"
      >
        <div className="w-12 h-12 rounded-full bg-[#00AEEF]/10 flex items-center justify-center shrink-0">
          {clientProfile.avatar ? (
            <img src={clientProfile.avatar} alt="" className="w-12 h-12 rounded-full object-cover" />
          ) : (
            <User className="w-6 h-6 text-[#00AEEF]" />
          )}
        </div>
        <div className="flex-1 min-w-0">
          <h3 className="font-semibold text-gray-900 dark:text-white truncate">{clientProfile.name}</h3>
          <div className="flex items-center gap-2 text-xs text-gray-500 dark:text-gray-400">
            <span className="flex items-center gap-1">
              <Dumbbell className="w-3 h-3" />
              {(clientProfile as Record<string, unknown>).program as string ?? 'No active program'}
            </span>
            <span>•</span>
            <span className="flex items-center gap-1">
              <TrendingUp className="w-3 h-3" />
              {(clientProfile as Record<string, unknown>).progress as number ?? 0}% compliance
            </span>
          </div>
        </div>
        <Badge
          variant="outline"
          className="text-[10px] border-green-200 text-green-600 dark:border-green-800 dark:text-green-400 bg-green-50 dark:bg-green-900/20"
        >
          Active
        </Badge>
      </motion.div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
        {/* Equipment Check */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.2 }}
          className="p-5 rounded-2xl bg-white dark:bg-[#141414] border border-gray-100 dark:border-white/5"
        >
          <div className="flex items-center gap-2 mb-4">
            <Dumbbell className="w-4 h-4 text-[#00AEEF]" />
            <h3 className="font-semibold text-sm text-gray-900 dark:text-white">Equipment Check</h3>
            <span className="ml-auto text-[10px] text-gray-400">
              {equipmentComparison.filter((e) => e.available).length}/{equipmentComparison.length} available
            </span>
          </div>
          <div className="space-y-2">
            {equipmentComparison.map((eq) => (
              <div
                key={eq.name}
                className={cn(
                  'flex items-center justify-between p-2.5 rounded-lg text-sm',
                  eq.available
                    ? 'bg-[#22C55E]/5 dark:bg-[#22C55E]/10'
                    : 'bg-red-50 dark:bg-red-900/10'
                )}
              >
                <span className="text-gray-700 dark:text-gray-200">{eq.name}</span>
                {eq.available ? (
                  <Check className="w-4 h-4 text-[#22C55E]" />
                ) : (
                  <X className="w-4 h-4 text-red-500" />
                )}
              </div>
            ))}
          </div>
          {equipmentComparison.some((e) => !e.available) && (
            <div className="mt-3 flex items-start gap-2 p-3 rounded-lg bg-amber-50 dark:bg-amber-900/10 border border-amber-200 dark:border-amber-800">
              <AlertTriangle className="w-4 h-4 text-amber-500 shrink-0 mt-0.5" />
              <p className="text-[11px] text-amber-700 dark:text-amber-400">
                Some required equipment is unavailable. Exercise substitutions will be suggested in the review step.
              </p>
            </div>
          )}
        </motion.div>

        {/* Availability Check */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.3 }}
          className="p-5 rounded-2xl bg-white dark:bg-[#141414] border border-gray-100 dark:border-white/5"
        >
          <div className="flex items-center gap-2 mb-4">
            <Calendar className="w-4 h-4 text-[#00AEEF]" />
            <h3 className="font-semibold text-sm text-gray-900 dark:text-white">Availability</h3>
            <span className="ml-auto text-[10px] text-gray-400">
              Need {methodDef?.frequency ?? '?'} days
            </span>
          </div>
          <div className="grid grid-cols-7 gap-1.5">
            {dayComparison.map((d) => (
              <div
                key={d.day}
                className={cn(
                  'flex flex-col items-center gap-1 p-2 rounded-lg text-center',
                  d.available
                    ? 'bg-[#22C55E]/5 dark:bg-[#22C55E]/10'
                    : 'bg-gray-50 dark:bg-white/5 opacity-40'
                )}
              >
                <span className="text-[10px] font-medium text-gray-600 dark:text-gray-300">{d.day}</span>
                {d.available ? (
                  <Check className="w-3.5 h-3.5 text-[#22C55E]" />
                ) : (
                  <X className="w-3.5 h-3.5 text-gray-300 dark:text-gray-600" />
                )}
              </div>
            ))}
          </div>
        </motion.div>

        {/* Safety / Pain Log */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.35 }}
          className="p-5 rounded-2xl bg-white dark:bg-[#141414] border border-gray-100 dark:border-white/5"
        >
          <div className="flex items-center gap-2 mb-4">
            <Shield className="w-4 h-4 text-[#00AEEF]" />
            <h3 className="font-semibold text-sm text-gray-900 dark:text-white">Safety Check</h3>
            <span className="ml-auto text-[10px] text-gray-400">
              {painEntries.length} active concern{painEntries.length !== 1 ? 's' : ''}
            </span>
          </div>

          {painEntries.length === 0 ? (
            <div className="flex items-center gap-2 p-3 rounded-lg bg-[#22C55E]/5 dark:bg-[#22C55E]/10">
              <Check className="w-4 h-4 text-[#22C55E]" />
              <p className="text-sm text-[#22C55E]">No pain or injury concerns logged.</p>
            </div>
          ) : (
            <div className="space-y-3">
              {painEntries.map((entry, i) => (
                <div
                  key={i}
                  className={cn('p-3 rounded-lg border', severityColor(entry.severity))}
                >
                  <div className="flex items-center gap-2 mb-2">
                    <AlertTriangle className="w-3.5 h-3.5 shrink-0" />
                    <span className="text-sm font-medium">{entry.bodyPart}</span>
                    <Badge variant="outline" className="text-[9px] capitalize ml-auto">
                      {entry.severity}
                    </Badge>
                  </div>
                  <div className="space-y-1.5">
                    <div>
                      <p className="text-[10px] uppercase tracking-wider opacity-70 font-medium">Avoid</p>
                      <div className="flex flex-wrap gap-1 mt-0.5">
                        {entry.exercisesToAvoid.map((ex) => (
                          <span key={ex} className="text-[10px] px-1.5 py-0.5 rounded bg-red-100/50 dark:bg-red-900/30 text-red-700 dark:text-red-300 line-through">
                            {ex}
                          </span>
                        ))}
                      </div>
                    </div>
                    <div>
                      <p className="text-[10px] uppercase tracking-wider opacity-70 font-medium">Use Instead</p>
                      <div className="flex flex-wrap gap-1 mt-0.5">
                        {entry.alternatives.map((alt) => (
                          <span key={alt} className="text-[10px] px-1.5 py-0.5 rounded bg-green-100/50 dark:bg-green-900/30 text-green-700 dark:text-green-300">
                            {alt}
                          </span>
                        ))}
                      </div>
                    </div>
                  </div>
                </div>
              ))}
            </div>
          )}
        </motion.div>

        {/* Prerequisite Benchmarks */}
        <motion.div
          initial={{ opacity: 0, y: 10 }}
          animate={{ opacity: 1, y: 0 }}
          transition={{ delay: 0.4 }}
          className="p-5 rounded-2xl bg-white dark:bg-[#141414] border border-gray-100 dark:border-white/5"
        >
          <div className="flex items-center gap-2 mb-4">
            <TrendingUp className="w-4 h-4 text-[#00AEEF]" />
            <h3 className="font-semibold text-sm text-gray-900 dark:text-white">Strength Benchmarks</h3>
          </div>

          <div className="space-y-2">
            {benchmarks.map((bm) => (
              <div
                key={bm.exercise}
                className={cn('flex items-center justify-between p-3 rounded-lg', benchmarkBg(bm.status))}
              >
                <div className="flex items-center gap-2">
                  <span className={cn('text-sm font-medium', benchmarkColor(bm.status))}>
                    {bm.exercise}
                  </span>
                </div>
                <div className="text-right">
                  <span className={cn('text-sm font-semibold', benchmarkColor(bm.status))}>
                    {bm.current}
                  </span>
                  <span className="text-[10px] text-gray-400 ml-1.5">
                    target {bm.target}
                  </span>
                </div>
              </div>
            ))}
          </div>
        </motion.div>
      </div>
    </div>
  );
}
