/**
 * AzFIT Program Data Utilities
 * Helper functions and data for program wizard components.
 */

import type { GoalType } from '@/types/program';
import { EXERCISE_DATABASE, MUSCLE_GROUPS, EQUIPMENT_TYPES } from './exercise-database';
import type { ExerciseData } from './exercise-database';

export function getExerciseLibrary(): ExerciseData[] {
  return EXERCISE_DATABASE;
}

export function getMuscleGroups(): string[] {
  return MUSCLE_GROUPS;
}

export function getEquipmentTypes(): string[] {
  return EQUIPMENT_TYPES;
}

export interface MethodOption {
  id: string;
  name: string;
  description: string;
  goal: GoalType;
  goals?: GoalType[];
  difficulty: string;
  estimatedWeeks: number;
  frequency?: string;
  duration?: string;
  equipment?: string;
  shortName?: string;
}

export const PROGRAM_METHODS: MethodOption[] = [
  { id: 'm1', name: 'Straight Sets', description: 'Traditional sets with full rest between', goal: 'strength', difficulty: 'beginner', estimatedWeeks: 8 },
  { id: 'm2', name: 'Supersets', description: 'Pair exercises back-to-back', goal: 'build-muscle', difficulty: 'intermediate', estimatedWeeks: 6 },
  { id: 'm3', name: 'Circuit Training', description: 'Continuous movement through stations', goal: 'lose-fat', difficulty: 'intermediate', estimatedWeeks: 6 },
  { id: 'm4', name: 'HIIT', description: 'High intensity interval training', goal: 'lose-fat', difficulty: 'advanced', estimatedWeeks: 4 },
  { id: 'm5', name: 'Periodized', description: 'Structured loading phases', goal: 'strength', difficulty: 'advanced', estimatedWeeks: 12 },
  { id: 'm6', name: 'Pyramid', description: 'Ascending/descending weight scheme', goal: 'build-muscle', difficulty: 'intermediate', estimatedWeeks: 8 },
];

export function getMethodsForGoal(goal: GoalType): MethodOption[] {
  return PROGRAM_METHODS.filter((m) => m.goal === goal || m.goals?.includes(goal));
}

export function getMethodById(id: string): MethodOption | undefined {
  return PROGRAM_METHODS.find((m) => m.id === id);
}

