export function getDifficultyColor(difficulty: string): string {
  const colors: Record<string, string> = {
    beginner: 'bg-emerald-100 text-emerald-700',
    intermediate: 'bg-yellow-100 text-yellow-700',
    advanced: 'bg-red-100 text-red-700',
    elite: 'bg-purple-100 text-purple-700',
  };
  return colors[difficulty] || 'bg-gray-100 text-gray-700';
}

export function calculateProgramVolume(exercises: Array<{ sets: number; reps: string }>): number {
  return exercises.reduce((total, ex) => {
    const repNum = parseInt(ex.reps.split('-')[0]) || 10;
    return total + ex.sets * repNum;
  }, 0);
}

export function calculateMuscleDistribution(exercises: Array<{ muscleGroup?: string; category?: string }>): Record<string, number> {
  const distribution: Record<string, number> = {};
  exercises.forEach((ex) => {
    const mg = ex.muscleGroup || ex.category || 'unknown';
    distribution[mg] = (distribution[mg] || 0) + 1;
  });
  return distribution;
}

export function estimateSessionTime(exerciseCount: number): number {
  return 15 + exerciseCount * 8; // rough estimate in minutes
}

export function generateWeeklySplit(days: number, goal: GoalType): string[] {
  const splits: Record<string, string[]> = {
    'lose-fat': ['Full Body A', 'Cardio + Core', 'Rest', 'Full Body B', 'HIIT', 'Rest', 'Rest'],
    'build-muscle': ['Push', 'Pull', 'Legs', 'Rest', 'Upper', 'Lower', 'Rest'],
    strength: ['Squat + Bench', 'Deadlift + OHP', 'Rest', 'Squat + Bench', 'Deadlift + OHP', 'Rest', 'Rest'],
    endurance: ['Cardio A', 'Strength A', 'Cardio B', 'Rest', 'Cardio C', 'Strength B', 'Rest'],
    maintenance: ['Upper', 'Lower', 'Rest', 'Full Body', 'Cardio', 'Rest', 'Rest'],
  };
  const base = splits[goal] || splits.maintenance;
  return base.slice(0, days).concat(Array(7 - days).fill('Rest'));
}
