/**
 * AzFIT Program Design Wizard — Step 6: Exercise Review & Block Organization
 *
 * Replaced the flat exercise table with a block-based organization system.
 * Trainers group exercises into blocks (straight, superset, triset, circuit, giant)
 * with Poliquin-style notation (A1, A2, B, C…). Supports drag-to-reorder,
 * inline editing, format switching, and exercise picking from the library.
 */

import { useState, useMemo } from 'react';
import { motion, AnimatePresence, Reorder } from 'framer-motion';
import {
  Plus,
  Layers,
  ChevronLeft,
  ChevronRight,
  CheckCircle,
  TrendingUp,
  Wand2,
} from 'lucide-react';
import type { ProgramExercise, Program, BlockFormat, ProgramExerciseBlock } from '@/types/program';
import { calculateMuscleDistribution } from '@/lib/program-data';
import { useProgramStore } from '@/stores/useProgramStore';
import ExerciseBlock from '@/components/program-wizard/ExerciseBlock';
import ExercisePickerDialog from './ExercisePickerDialog';

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface ExerciseReviewStepProps {
  /** The program being built */
  program: Program;
  /** Called when an exercise field is updated */
  onUpdateExercise: (dayOfWeek: string, exerciseId: string, updates: Partial<ProgramExercise>) => void;
  /** Called when an exercise is swapped */
  onSwapExercise: (dayOfWeek: string, oldExerciseId: string, newExercise: ProgramExercise) => void;
  /** Called when user completes this step */
  onNext: () => void;
  /** Called when user wants to go back */
  onBack: () => void;
}

const EASING = [0.16, 1, 0.3, 1] as [number, number, number, number];

/** Day labels */
const DAY_LABELS = ['Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat', 'Sun'];
const DAY_NAMES = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday'];

/** Color mapping for muscle group distribution bars */
const MUSCLE_COLORS: Record<string, string> = {
  Chest: 'bg-red-400',
  Back: 'bg-blue-400',
  Legs: 'bg-emerald-400',
  Shoulders: 'bg-purple-400',
  Arms: 'bg-orange-400',
  Core: 'bg-yellow-400',
};

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function ExerciseReviewStep({
  program,
  onSwapExercise,
  onNext,
  onBack,
}: ExerciseReviewStepProps) {
  // ── Zustand block state ──
  const blocks = useProgramStore((s) => s.wizard.wizardBlocks);
  const addBlock = useProgramStore((s) => s.addBlock);
  const removeBlock = useProgramStore((s) => s.removeBlock);
  const updateBlock = useProgramStore((s) => s.updateBlock);
  const autoAssignGroups = useProgramStore((s) => s.autoAssignGroups);
  const addExerciseToBlock = useProgramStore((s) => s.addExerciseToBlock);
  const removeExerciseFromBlock = useProgramStore((s) => s.removeExerciseFromBlock);
  const updateBlockExercise = useProgramStore((s) => s.updateBlockExercise);
  const reorderExercisesInBlock = useProgramStore((s) => s.reorderExercisesInBlock);
  const reorderBlocks = useProgramStore((s) => s.reorderBlocks);
  const autoPopulateBlocks = useProgramStore((s) => s.autoPopulateBlocks);
  const wizard = useProgramStore((s) => s.wizard);

  // ── Local state ──
  const [selectedDay, setSelectedDay] = useState<string>('all');
  const [swapDialogOpen, setSwapDialogOpen] = useState(false);
  const [swapTarget, setSwapTarget] = useState<{
    dayOfWeek: string;
    exerciseId: string;
  } | null>(null);

  // ── Group blocks by day ──
  const blocksByDay = useMemo(() => {
    const grouped: Record<number, ProgramExerciseBlock[]> = {};
    blocks.forEach((block) => {
      if (block.dayIndex < 0 || block.dayIndex > 6) return;
      if (!grouped[block.dayIndex]) grouped[block.dayIndex] = [];
      grouped[block.dayIndex].push(block);
    });
    // Sort by order within each day
    Object.values(grouped).forEach((dayBlocks) => {
      dayBlocks.sort((a, b) => a.order - b.order);
    });
    return grouped;
  }, [blocks]);

  // ── Training days that have blocks ──
  const activeDays = useMemo(() => {
    return Object.keys(blocksByDay)
      .map(Number)
      .sort((a, b) => a - b);
  }, [blocksByDay]);

  // ── Filtered days for display ──
  const displayDays = useMemo(() => {
    if (selectedDay === 'all') return activeDays;
    const idx = DAY_LABELS.indexOf(selectedDay);
    return idx >= 0 && blocksByDay[idx] ? [idx] : [];
  }, [selectedDay, activeDays, blocksByDay]);

  // ── Muscle distribution from blocks ──
  const muscleDistribution = useMemo(() => {
    const allExs = blocks.flatMap((b) => b.exercises);
    // Convert BlockExercise shape to something calculateMuscleDistribution can use
    const pseudoExercises = allExs.map((ex) => ({
      exerciseId: ex.exerciseId,
      name: ex.name,
      muscleGroup: 'General',
      equipment: 'General',
      sets: ex.sets,
      reps: ex.reps,
      weight: '',
      rest: ex.rest,
      tempo: ex.tempo,
      supersetWith: null,
      order: 0,
      notes: ex.notes ?? '',
      isSubstituted: false,
      originalExerciseId: null,
    })) as ProgramExercise[];
    return calculateMuscleDistribution(pseudoExercises);
  }, [blocks]);

  /** Count total exercises across all blocks */
  const totalExercises = useMemo(() => {
    return blocks.reduce((acc, b) => acc + b.exercises.length, 0);
  }, [blocks]);

  /** Count blocks */
  const totalBlocks = blocks.length;

  // ── Handlers ──

  /** Create a new empty block for a specific day */
  const handleAddBlock = (dayIndex: number) => {
    const dayLabel = DAY_LABELS[dayIndex] ?? 'Unassigned';
    const existingCount = blocksByDay[dayIndex]?.length ?? 0;
    addBlock({
      name: `${dayLabel} Block ${existingCount + 1}`,
      format: 'straight' as BlockFormat,
      exercises: [],
      dayIndex,
      order: existingCount,
    });
  };

  /** Create a new unassigned block */
  const handleAddUnassignedBlock = () => {
    const existingUnassigned = blocks.filter((b) => b.dayIndex === -1).length;
    addBlock({
      name: `Unassigned ${existingUnassigned + 1}`,
      format: 'straight',
      exercises: [],
      dayIndex: -1,
      order: existingUnassigned,
    });
  };

  /** Auto-populate blocks from the program's exercises */
  const handleAutoPopulate = () => {
    if (wizard.selectedMethod && wizard.selectedGoal) {
      autoPopulateBlocks(wizard.selectedMethod, wizard.selectedGoal);
    }
  };

  /** Get focus label for a day */
  const getDayFocus = (dayIndex: number): string => {
    const day = program.weeklySplit[dayIndex];
    return day?.focus ?? `${DAY_NAMES[dayIndex]} Focus`;
  };

  return (
    <div className="space-y-6">
      {/* ── Header ── */}
      <div className="text-center">
        <h2 className="text-2xl font-bold text-gray-900 dark:text-white">
          Exercise Review
        </h2>
        <p className="text-gray-500 dark:text-gray-400 mt-1 text-sm">
          Organize exercises into training blocks with Poliquin-style notation
        </p>
      </div>

      {/* ── Muscle Group Distribution Bar ── */}
      <div className="p-4 rounded-xl bg-white dark:bg-[#141414] border border-gray-200 dark:border-white/10">
        <div className="flex items-center justify-between mb-3">
          <h3 className="text-sm font-semibold text-gray-800 dark:text-gray-200 flex items-center gap-2">
            <TrendingUp className="w-4 h-4 text-[#00AEEF]" />
            Muscle Group Distribution
          </h3>
          <span className="text-xs text-gray-400">{totalExercises} exercises</span>
        </div>

        {/* Stacked percentage bar */}
        <div className="flex h-3 rounded-full overflow-hidden mb-2">
          {muscleDistribution.map((m) => (
            <div
              key={m.muscleGroup}
              className={`${MUSCLE_COLORS[m.muscleGroup] || 'bg-gray-400'} h-full`}
              style={{ width: `${m.percentage}%` }}
              title={`${m.muscleGroup}: ${m.percentage}%`}
            />
          ))}
        </div>

        {/* Legend */}
        <div className="flex flex-wrap gap-3">
          {muscleDistribution.map((m) => (
            <div key={m.muscleGroup} className="flex items-center gap-1.5">
              <div className={`w-2.5 h-2.5 rounded-full ${MUSCLE_COLORS[m.muscleGroup] || 'bg-gray-400'}`} />
              <span className="text-xs text-gray-600 dark:text-gray-400">
                {m.muscleGroup}{' '}
                <strong className="text-gray-800 dark:text-gray-300">{m.percentage}%</strong>
              </span>
            </div>
          ))}
        </div>
      </div>

      {/* ── Summary Stats ── */}
      <div className="flex items-center gap-4 text-sm">
        <div className="flex items-center gap-1.5 text-gray-600 dark:text-gray-400">
          <Layers className="w-4 h-4 text-[#22C55E]" />
          <span>
            <strong className="text-gray-900 dark:text-white">{totalBlocks}</strong> blocks
          </span>
        </div>
        <div className="flex items-center gap-1.5 text-gray-600 dark:text-gray-400">
          <CheckCircle className="w-4 h-4 text-[#00AEEF]" />
          <span>
            <strong className="text-gray-900 dark:text-white">{totalExercises}</strong> exercises
          </span>
        </div>
      </div>

      {/* ── Toolbar: Add Block + Auto-Populate ── */}
      <div className="flex flex-wrap items-center gap-2">
        <button
          onClick={handleAddUnassignedBlock}
          className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-semibold bg-[#00AEEF] text-white hover:bg-[#0095CC] shadow-lg shadow-[#00AEEF]/25 transition-all"
        >
          <Plus className="w-3.5 h-3.5" />
          Add New Block
        </button>

        <button
          onClick={() => {
            blocks.forEach((b) => autoAssignGroups(b.id));
          }}
          className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 hover:border-[#00AEEF]/50 transition-colors"
        >
          <Wand2 className="w-3.5 h-3.5 text-purple-500" />
          Auto-Assign Groups
        </button>

        {blocks.length === 0 && (
          <button
            onClick={handleAutoPopulate}
            className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 hover:border-[#00AEEF]/50 transition-colors"
          >
            <TrendingUp className="w-3.5 h-3.5 text-[#22C55E]" />
            Auto-Populate from Program
          </button>
        )}

        <span className="ml-auto text-xs text-gray-400">
          {blocks.length} block{blocks.length !== 1 ? 's' : ''}
        </span>
      </div>

      {/* ── Day Filter ── */}
      <div className="flex items-center gap-2">
        <button
          onClick={() => setSelectedDay('all')}
          className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
            selectedDay === 'all'
              ? 'bg-[#00AEEF] text-white'
              : 'bg-gray-100 text-gray-600 dark:bg-[#1a1a1a] dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-[#222]'
          }`}
        >
          All Days
        </button>
        {DAY_LABELS.map((day, i) => {
          const hasBlocks = blocksByDay[i] && blocksByDay[i].length > 0;
          return (
            <button
              key={day}
              onClick={() => setSelectedDay(day)}
              className={`px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                selectedDay === day
                  ? 'bg-[#00AEEF] text-white'
                  : hasBlocks
                  ? 'bg-gray-100 text-gray-600 dark:bg-[#1a1a1a] dark:text-gray-400 hover:bg-gray-200 dark:hover:bg-[#222]'
                  : 'bg-gray-50 text-gray-300 dark:bg-[#111] dark:text-gray-600 cursor-default'
              }`}
            >
              {day}
            </button>
          );
        })}
      </div>

      {/* ── Blocks by Day ── */}
      <div className="space-y-8">
        <AnimatePresence mode="popLayout">
          {displayDays.map((dayIndex) => (
            <motion.div
              key={dayIndex}
              layout
              initial={{ opacity: 0, y: 10 }}
              animate={{ opacity: 1, y: 0 }}
              exit={{ opacity: 0, y: -10 }}
              transition={{ duration: 0.25, ease: EASING }}
              className="space-y-3"
            >
              {/* Day header */}
              <div className="flex items-center gap-2">
                <h3 className="text-sm font-bold text-gray-800 dark:text-gray-200">
                  {DAY_NAMES[dayIndex]}
                </h3>
                <span className="text-xs text-gray-400">— {getDayFocus(dayIndex)}</span>
                <span className="ml-auto text-xs text-gray-400">
                  {blocksByDay[dayIndex]?.length ?? 0} block
                  {(blocksByDay[dayIndex]?.length ?? 0) !== 1 ? 's' : ''}
                </span>
              </div>

              {/* Blocks for this day */}
              <Reorder.Group
                axis="y"
                values={blocksByDay[dayIndex] ?? []}
                onReorder={(reordered) => {
                  const ids = reordered.map((b) => b.id);
                  reorderBlocks(ids);
                }}
                className="space-y-3"
              >
                <AnimatePresence>
                  {(blocksByDay[dayIndex] ?? []).map((block) => (
                    <Reorder.Item key={block.id} value={block} dragListener={false}>
                      <ExerciseBlock
                        block={block}
                        onUpdateName={(name) => updateBlock(block.id, { name })}
                        onUpdateFormat={(format) => {
                          updateBlock(block.id, { format });
                          // Re-run auto-assign after format change
                          setTimeout(() => autoAssignGroups(block.id), 0);
                        }}
                        onDeleteBlock={() => removeBlock(block.id)}
                        onUpdateExercise={(exerciseId, data) =>
                          updateBlockExercise(block.id, exerciseId, data)
                        }
                        onRemoveExercise={(exerciseId) =>
                          removeExerciseFromBlock(block.id, exerciseId)
                        }
                        onReorderExercises={(exerciseIds) =>
                          reorderExercisesInBlock(block.id, exerciseIds)
                        }
                        onAddExercise={(exercise) =>
                          addExerciseToBlock(block.id, exercise)
                        }
                      />
                    </Reorder.Item>
                  ))}
                </AnimatePresence>
              </Reorder.Group>

              {/* Add block button for this day */}
              <button
                onClick={() => handleAddBlock(dayIndex)}
                className="flex items-center gap-1.5 px-3 py-2 rounded-xl text-xs font-medium text-gray-500 dark:text-gray-400 hover:text-[#00AEEF] hover:bg-[#00AEEF]/10 transition-colors"
              >
                <Plus className="w-3.5 h-3.5" />
                Add Block to {DAY_NAMES[dayIndex]}
              </button>
            </motion.div>
          ))}
        </AnimatePresence>

        {/* Empty state */}
        {blocks.length === 0 && (
          <motion.div
            initial={{ opacity: 0 }}
            animate={{ opacity: 1 }}
            className="text-center py-12 rounded-xl border-2 border-dashed border-gray-200 dark:border-white/10"
          >
            <Layers className="w-10 h-10 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
            <h3 className="text-sm font-semibold text-gray-700 dark:text-gray-300 mb-1">
              No Training Blocks Yet
            </h3>
            <p className="text-xs text-gray-400 dark:text-gray-500 mb-4">
              Create blocks to organize your exercises with Poliquin-style notation
            </p>
            <div className="flex items-center justify-center gap-2">
              <button
                onClick={handleAddUnassignedBlock}
                className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-semibold bg-[#00AEEF] text-white hover:bg-[#0095CC] transition-colors"
              >
                <Plus className="w-3.5 h-3.5" />
                Add Your First Block
              </button>
              {wizard.selectedMethod && wizard.selectedGoal && (
                <button
                  onClick={handleAutoPopulate}
                  className="flex items-center gap-1.5 px-4 py-2 rounded-xl text-xs font-medium bg-white dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-700 dark:text-gray-300 hover:border-[#00AEEF]/50 transition-colors"
                >
                  <TrendingUp className="w-3.5 h-3.5 text-[#22C55E]" />
                  Auto-Populate
                </button>
              )}
            </div>
          </motion.div>
        )}
      </div>

      {/* ── Navigation ── */}
      <div className="flex items-center justify-between pt-6 border-t border-gray-100 dark:border-white/5">
        <button
          onClick={onBack}
          className="flex items-center gap-2 px-5 py-2.5 rounded-xl text-sm font-medium text-gray-600 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-white/5 transition-colors"
        >
          <ChevronLeft className="w-4 h-4" />
          Back
        </button>
        <button
          onClick={onNext}
          className="flex items-center gap-2 px-6 py-2.5 rounded-xl text-sm font-semibold bg-[#00AEEF] text-white hover:bg-[#0095CC] shadow-lg shadow-[#00AEEF]/25 transition-all duration-200"
        >
          Continue to Preview
          <ChevronRight className="w-4 h-4" />
        </button>
      </div>

      {/* ── Legacy Exercise Picker Dialog (kept for swap compat) ── */}
      <ExercisePickerDialog
        open={swapDialogOpen}
        onClose={() => {
          setSwapDialogOpen(false);
          setSwapTarget(null);
        }}
        onSelectExercise={(exercise) => {
          if (swapTarget) {
            const programExercise: ProgramExercise = {
              exerciseId: exercise.id,
              name: exercise.name,
              muscleGroup: exercise.muscleGroup,
              equipment: exercise.equipment,
              sets: 3,
              reps: '8-10',
              weight: 'RPE 8',
              rest: '90s',
              tempo: '3010',
              supersetWith: null,
              order: 1,
              notes: '',
              isSubstituted: true,
              originalExerciseId: swapTarget.exerciseId ?? null,
            };
            onSwapExercise(swapTarget.dayOfWeek, swapTarget.exerciseId, programExercise);
          }
          setSwapDialogOpen(false);
          setSwapTarget(null);
        }}
        currentExerciseName={
          swapTarget
            ? program.weeklySplit
                .flatMap((d) => d.exercises.map((e) => ({ ...e, dayOfWeek: d.dayOfWeek })))
                .find((r) => r.dayOfWeek === swapTarget.dayOfWeek && r.exerciseId === swapTarget.exerciseId)
                ?.name
            : undefined
        }
      />
    </div>
  );
}
