/**
 * AzFIT Program Design Wizard — Exercise Picker Dialog
 *
 * Modal dialog that allows trainers to search and filter the exercise library
 * to find replacement exercises. Supports filtering by muscle group, equipment,
 * difficulty, and exercise type with real-time search.
 */

import { useState, useMemo } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import {
  Search,
  X,
  Dumbbell,
  Filter,
  Target,
  Zap,
  BarChart3,
  Check,
  ArrowLeftRight,
} from 'lucide-react';
import type { ExerciseDefinition } from '@/types/program';
import { getExerciseLibrary, getMuscleGroups, getEquipmentTypes } from '@/lib/program-data';
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from '@/components/ui/dialog';

// ─────────────────────────────────────────────────────────────────────────────
// Props
// ─────────────────────────────────────────────────────────────────────────────

interface ExercisePickerDialogProps {
  /** Whether the dialog is open */
  open: boolean;
  /** Called when the dialog should close */
  onClose: () => void;
  /** Called when an exercise is selected */
  onSelectExercise: (exercise: ExerciseDefinition) => void;
  /** Name of the exercise being replaced (for context) */
  currentExerciseName?: string;
}

/** Filter options */
const DIFFICULTY_OPTIONS = ['All', 'Beginner', 'Intermediate', 'Advanced'];
const TYPE_OPTIONS = ['All', 'Compound', 'Isolation', 'Olympic'];

// ─────────────────────────────────────────────────────────────────────────────
// Component
// ─────────────────────────────────────────────────────────────────────────────

export default function ExercisePickerDialog({
  open,
  onClose,
  onSelectExercise,
  currentExerciseName,
}: ExercisePickerDialogProps) {
  /** Search query string */
  const [searchQuery, setSearchQuery] = useState('');
  /** Active filters */
  const [muscleGroup, setMuscleGroup] = useState('All');
  const [equipment, setEquipment] = useState('All');
  const [difficulty, setDifficulty] = useState('All');
  const [type, setType] = useState('All');
  /** Whether filter panel is expanded */
  const [showFilters, setShowFilters] = useState(false);

  /** Full exercise library */
  const exercises = useMemo(() => getExerciseLibrary(), []);
  const muscleGroups = useMemo(() => getMuscleGroups(), []);
  const equipmentTypes = useMemo(() => getEquipmentTypes(), []);

  /** Filtered exercise results */
  const filteredExercises = useMemo(() => {
    return exercises.filter((ex: ExerciseDefinition) => {
      // Text search across name, muscle group, equipment, and description
      if (searchQuery.trim()) {
        const q = searchQuery.toLowerCase();
        const searchable = `${ex.name} ${ex.muscleGroup} ${ex.equipment} ${ex.description}`.toLowerCase();
        if (!searchable.includes(q)) return false;
      }

      // Apply dropdown filters
      if (muscleGroup !== 'All' && ex.muscleGroup !== muscleGroup) return false;
      if (equipment !== 'All' && ex.equipment !== equipment) return false;
      if (difficulty !== 'All' && ex.difficulty !== difficulty.toLowerCase()) return false;
      if (type !== 'All' && ex.type !== type.toLowerCase()) return false;

      return true;
    });
  }, [exercises, searchQuery, muscleGroup, equipment, difficulty, type]);

  /** Get difficulty badge color */
  const getDifficultyBadgeColor = (diff: string): string => {
    switch (diff) {
      case 'beginner':
        return 'bg-green-100 text-green-700 dark:bg-green-900/30 dark:text-green-400';
      case 'intermediate':
        return 'bg-yellow-100 text-yellow-700 dark:bg-yellow-900/30 dark:text-yellow-400';
      case 'advanced':
        return 'bg-red-100 text-red-700 dark:bg-red-900/30 dark:text-red-400';
      default:
        return 'bg-gray-100 text-gray-600 dark:bg-gray-800 dark:text-gray-400';
    }
  };

  /** Get exercise type icon */
  const getTypeIcon = (exerciseType: string) => {
    switch (exerciseType) {
      case 'compound':
        return <Target className="w-3.5 h-3.5 text-blue-500" />;
      case 'isolation':
        return <Zap className="w-3.5 h-3.5 text-orange-500" />;
      case 'olympic':
        return <BarChart3 className="w-3.5 h-3.5 text-purple-500" />;
      default:
        return <Dumbbell className="w-3.5 h-3.5 text-gray-400" />;
    }
  };

  /** Reset all filters */
  const handleResetFilters = () => {
    setSearchQuery('');
    setMuscleGroup('All');
    setEquipment('All');
    setDifficulty('All');
    setType('All');
  };

  /** Count active filters */
  const activeFilterCount = [muscleGroup, equipment, difficulty, type].filter(
    (f) => f !== 'All'
  ).length;

  return (
    <Dialog open={open} onOpenChange={(isOpen) => !isOpen && onClose()}>
      <DialogContent className="max-w-3xl max-h-[85vh] overflow-hidden flex flex-col p-0 gap-0 bg-white dark:bg-[#141414]">
        {/* ── Header ── */}
        <DialogHeader className="p-6 pb-4 border-b border-gray-100 dark:border-white/5">
          <DialogTitle className="flex items-center gap-2 text-lg font-bold text-gray-900 dark:text-white">
            <ArrowLeftRight className="w-5 h-5 text-[#00AEEF]" />
            Swap Exercise
          </DialogTitle>
          <DialogDescription className="text-sm text-gray-500 dark:text-gray-400">
            {currentExerciseName
              ? `Replacing: ${currentExerciseName}`
              : 'Select a new exercise from the library'}
          </DialogDescription>
        </DialogHeader>

        {/* ── Search & Filters ── */}
        <div className="px-6 py-4 border-b border-gray-100 dark:border-white/5 space-y-3">
          {/* Search bar */}
          <div className="relative">
            <Search className="absolute left-3 top-1/2 -translate-y-1/2 w-4 h-4 text-gray-400" />
            <input
              type="text"
              placeholder="Search exercises..."
              value={searchQuery}
              onChange={(e) => setSearchQuery(e.target.value)}
              className="w-full pl-10 pr-4 py-2.5 rounded-xl text-sm bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white placeholder:text-gray-400 focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30 focus:border-[#00AEEF] transition-all"
            />
            {searchQuery && (
              <button
                onClick={() => setSearchQuery('')}
                className="absolute right-3 top-1/2 -translate-y-1/2 text-gray-400 hover:text-gray-600"
              >
                <X className="w-4 h-4" />
              </button>
            )}
          </div>

          {/* Filter toggle */}
          <div className="flex items-center gap-2">
            <button
              onClick={() => setShowFilters(!showFilters)}
              className={`flex items-center gap-1.5 px-3 py-1.5 rounded-lg text-xs font-medium transition-colors ${
                showFilters || activeFilterCount > 0
                  ? 'bg-[#00AEEF]/10 text-[#00AEEF]'
                  : 'bg-gray-100 text-gray-600 dark:bg-[#1a1a1a] dark:text-gray-400'
              }`}
            >
              <Filter className="w-3.5 h-3.5" />
              Filters
              {activeFilterCount > 0 && (
                <span className="ml-0.5 px-1.5 py-0.5 rounded-full bg-[#00AEEF] text-white text-[10px] font-bold">
                  {activeFilterCount}
                </span>
              )}
            </button>
            {activeFilterCount > 0 && (
              <button
                onClick={handleResetFilters}
                className="text-xs text-gray-500 hover:text-gray-700 dark:text-gray-400 dark:hover:text-gray-300 transition-colors"
              >
                Reset
              </button>
            )}
            <span className="ml-auto text-xs text-gray-400">
              {filteredExercises.length} result{filteredExercises.length !== 1 ? 's' : ''}
            </span>
          </div>

          {/* Filter panel */}
          <AnimatePresence>
            {showFilters && (
              <motion.div
                initial={{ height: 0, opacity: 0 }}
                animate={{ height: 'auto', opacity: 1 }}
                exit={{ height: 0, opacity: 0 }}
                transition={{ duration: 0.2 }}
                className="overflow-hidden"
              >
                <div className="grid grid-cols-2 sm:grid-cols-4 gap-3 pt-2">
                  {/* Muscle Group filter */}
                  <div>
                    <label className="block text-[10px] font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-1">
                      Muscle Group
                    </label>
                    <select
                      value={muscleGroup}
                      onChange={(e) => setMuscleGroup(e.target.value)}
                      className="w-full px-2 py-1.5 rounded-lg text-xs bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
                    >
                      {muscleGroups.map((g) => (
                        <option key={g} value={g}>
                          {g}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Equipment filter */}
                  <div>
                    <label className="block text-[10px] font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-1">
                      Equipment
                    </label>
                    <select
                      value={equipment}
                      onChange={(e) => setEquipment(e.target.value)}
                      className="w-full px-2 py-1.5 rounded-lg text-xs bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
                    >
                      {equipmentTypes.map((e) => (
                        <option key={e} value={e}>
                          {e}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Difficulty filter */}
                  <div>
                    <label className="block text-[10px] font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-1">
                      Difficulty
                    </label>
                    <select
                      value={difficulty}
                      onChange={(e) => setDifficulty(e.target.value)}
                      className="w-full px-2 py-1.5 rounded-lg text-xs bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
                    >
                      {DIFFICULTY_OPTIONS.map((d) => (
                        <option key={d} value={d}>
                          {d}
                        </option>
                      ))}
                    </select>
                  </div>

                  {/* Type filter */}
                  <div>
                    <label className="block text-[10px] font-medium text-gray-500 dark:text-gray-400 uppercase tracking-wider mb-1">
                      Type
                    </label>
                    <select
                      value={type}
                      onChange={(e) => setType(e.target.value)}
                      className="w-full px-2 py-1.5 rounded-lg text-xs bg-gray-50 dark:bg-[#1a1a1a] border border-gray-200 dark:border-white/10 text-gray-900 dark:text-white focus:outline-none focus:ring-2 focus:ring-[#00AEEF]/30"
                    >
                      {TYPE_OPTIONS.map((t) => (
                        <option key={t} value={t}>
                          {t}
                        </option>
                      ))}
                    </select>
                  </div>
                </div>
              </motion.div>
            )}
          </AnimatePresence>
        </div>

        {/* ── Results List ── */}
        <div className="flex-1 overflow-y-auto px-6 py-2">
          <div className="space-y-2">
            <AnimatePresence>
              {filteredExercises.map((ex: ExerciseDefinition, index: number) => (
                <motion.div
                  key={ex.id}
                  initial={{ opacity: 0, y: 5 }}
                  animate={{ opacity: 1, y: 0 }}
                  exit={{ opacity: 0, y: -5 }}
                  transition={{ delay: index * 0.02 }}
                  className="group flex items-start gap-3 p-3 rounded-xl border border-gray-100 dark:border-white/5 bg-gray-50/50 dark:bg-[#1a1a1a]/50 hover:border-[#00AEEF]/30 hover:bg-[#00AEEF]/[0.02] dark:hover:bg-[#00AEEF]/[0.02] transition-all"
                >
                  {/* Exercise info */}
                  <div className="flex-1 min-w-0">
                    <div className="flex items-center gap-2 mb-1">
                      <span className="font-semibold text-sm text-gray-900 dark:text-white truncate">
                        {ex.name}
                      </span>
                      <span
                        className={`shrink-0 px-1.5 py-0.5 rounded-full text-[10px] font-medium ${getDifficultyBadgeColor(
                          ex.difficulty
                        )}`}
                      >
                        {ex.difficulty.charAt(0).toUpperCase() + ex.difficulty.slice(1)}
                      </span>
                    </div>

                    <div className="flex items-center gap-2 mb-1.5 flex-wrap">
                      <span className="flex items-center gap-1 text-[10px] text-gray-500 dark:text-gray-400">
                        <Target className="w-3 h-3" />
                        {ex.muscleGroup}
                      </span>
                      <span className="text-gray-300">·</span>
                      <span className="flex items-center gap-1 text-[10px] text-gray-500 dark:text-gray-400">
                        <Dumbbell className="w-3 h-3" />
                        {ex.equipment}
                      </span>
                      <span className="text-gray-300">·</span>
                      <span className="flex items-center gap-1 text-[10px] text-gray-500 dark:text-gray-400">
                        {getTypeIcon(ex.type)}
                        {ex.type.charAt(0).toUpperCase() + ex.type.slice(1)}
                      </span>
                    </div>

                    <p className="text-[11px] text-gray-500 dark:text-gray-500 line-clamp-2">
                      {ex.description}
                    </p>
                  </div>

                  {/* Select button */}
                  <button
                    onClick={() => onSelectExercise(ex)}
                    className="shrink-0 flex items-center gap-1.5 px-3 py-2 rounded-lg text-xs font-medium bg-[#00AEEF] text-white hover:bg-[#0095CC] shadow-sm transition-all opacity-0 group-hover:opacity-100 focus:opacity-100"
                  >
                    <Check className="w-3.5 h-3.5" />
                    Select
                  </button>
                </motion.div>
              ))}
            </AnimatePresence>

            {filteredExercises.length === 0 && (
              <div className="text-center py-12">
                <Search className="w-8 h-8 text-gray-300 dark:text-gray-600 mx-auto mb-3" />
                <p className="text-sm text-gray-500 dark:text-gray-400">
                  No exercises match your filters
                </p>
                <button
                  onClick={handleResetFilters}
                  className="mt-2 text-xs text-[#00AEEF] hover:underline"
                >
                  Reset all filters
                </button>
              </div>
            )}
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}
